// ---------------- Smooth territory/continent boundary rendering ----------------
// Territories are still just sets of grid cells underneath (adjacency, ownership, click
// hit-testing all stay cell-based) — this only affects how a territory's outline is DRAWN:
// its outer edge (and any water "holes" inside it) is traced by walking cell edges (marching-
// squares style), then rounded from blocky right angles into an organic curve with a couple
// passes of Chaikin's corner-cutting algorithm. Purely a rendering concern.
//
// inSet(c,r) => whether cell (c,r) belongs to the mask being traced. Emitting each filled
// cell's edges in this specific order/direction makes the outer boundary of a blob come out
// clockwise and any hole inside it come out counter-clockwise automatically — which is exactly
// what canvas's default "nonzero" fill rule needs to render holes as holes.
//
// idFn(c,r) => whatever "identity" (territory id, continent id, or -1 for empty/off-map) sits
// on the OUTSIDE of the traced edge at that cell — recorded per edge so douglasPeuckerRun()
// below can later simplify "the stretch of boundary facing one specific neighbor" as its own
// fixed-endpoint unit. That stretch is exactly what two adjacent shapes SHARE, so both sides
// see the same start/end anchors for it regardless of where their own trace happened to start —
// see the big comment on splitLoopIntoRuns() for why that's the whole point.
function traceMaskBoundary(inSet, idFn){
  const edges = new Map(); // "x_y" (edge start corner) -> {to:[x2,y2], outside: identity}
  const k = (x,y)=> x+'_'+y;
  inSet.cells.forEach(([c,r])=>{
    if(!inSet(c,r-1)) edges.set(k(c,r), {to:[c+1,r], outside:idFn(c,r-1)});
    if(!inSet(c+1,r)) edges.set(k(c+1,r), {to:[c+1,r+1], outside:idFn(c+1,r)});
    if(!inSet(c,r+1)) edges.set(k(c+1,r+1), {to:[c,r+1], outside:idFn(c,r+1)});
    if(!inSet(c-1,r)) edges.set(k(c,r+1), {to:[c,r], outside:idFn(c-1,r)});
  });
  const loops = [];
  const visited = new Set();
  for(const startKey of edges.keys()){
    if(visited.has(startKey)) continue;
    const points = [], edgeIds = [];
    let curKey = startKey, guard = 0;
    while(!visited.has(curKey) && edges.has(curKey) && guard++<200000){
      visited.add(curKey);
      points.push(curKey.split('_').map(Number));
      const edge = edges.get(curKey);
      edgeIds.push(edge.outside);
      curKey = k(edge.to[0], edge.to[1]);
    }
    if(points.length>=3) loops.push({points, edgeIds});
  }
  return loops;
}

// One pass replaces each edge (P0,P1) with 2 points at 25%/75% along it, cutting every corner
// down and rounding it; a couple of passes is enough to look like a smooth organic curve.
// NOTE: Chaikin moves EVERY point on EVERY pass, including points that represent a real corner
// of the shape, not just staircase noise — it can't tell the difference. That's what
// douglasPeuckerLoop() below is for: run BEFORE this, it drops only the points that don't
// represent a meaningful bend, so the corners Chaikin then rounds are the ones that matter.
function chaikinSmooth(loop, iterations){
  let pts = loop;
  for(let it=0; it<iterations; it++){
    const next = []; const n = pts.length;
    for(let i=0;i<n;i++){
      const [x0,y0] = pts[i]; const [x1,y1] = pts[(i+1)%n];
      next.push([x0+(x1-x0)*0.25, y0+(y1-y0)*0.25]);
      next.push([x0+(x1-x0)*0.75, y0+(y1-y0)*0.75]);
    }
    pts = next;
  }
  return pts;
}

// Same corner-cutting as chaikinSmooth(), but for an OPEN run whose first/last point must stay
// at their EXACT original coordinates (only the interior corners get rounded). This matters for
// douglasPeuckerRuns-simplified boundaries: a run's endpoints are the neighbor-transition points
// shared with an adjacent shape's own run (see splitLoopIntoRuns() below) — if this rounded them
// too, two adjacent shapes would each pull that shared corner back by however much rounding its
// OWN, unrelated neighboring run happened to need, and end up disagreeing on where the corner
// actually is (confirmed empirically: this was the real remaining cause of the ~11% shared-edge
// gap that persisted even after switching to neighbor-aware run splitting — Douglas-Peucker
// picking the same anchors wasn't enough on its own, since a plain closed-loop Chaikin pass
// right after still re-rounded those exact anchors by a different amount on each side).
function chaikinSmoothOpen(points, iterations){
  if(points.length<3) return points.slice();
  let pts = points;
  for(let it=0; it<iterations; it++){
    const next = [pts[0]];
    for(let i=0;i<pts.length-1;i++){
      const [x0,y0] = pts[i]; const [x1,y1] = pts[i+1];
      next.push([x0+(x1-x0)*0.25, y0+(y1-y0)*0.25]);
      next.push([x0+(x1-x0)*0.75, y0+(y1-y0)*0.75]);
    }
    next.push(pts[pts.length-1]);
    pts = next;
  }
  return pts;
}

function distSq(a,b){ const dx=a[0]-b[0], dy=a[1]-b[1]; return dx*dx+dy*dy; }

// Perpendicular distance from point p to the infinite line through a,b (0 if a===b).
function pointLineDistance(p, a, b){
  const dx=b[0]-a[0], dy=b[1]-a[1];
  const lenSq = dx*dx+dy*dy;
  if(lenSq===0) return Math.hypot(p[0]-a[0], p[1]-a[1]);
  const t = ((p[0]-a[0])*dx+(p[1]-a[1])*dy)/lenSq;
  const projX = a[0]+t*dx, projY = a[1]+t*dy;
  return Math.hypot(p[0]-projX, p[1]-projY);
}

// Standard recursive Douglas-Peucker on an OPEN polyline: points[0] and the last point are
// always kept exactly where they are; everything between them is dropped UNLESS some point
// deviates from the straight line (points[0]->last) by more than epsilon, in which case that
// point is kept too (becoming a new fixed anchor) and both halves are simplified the same way.
//
// TIE-BREAK NOTE: a staircase boundary is full of EXACT ties for "farthest point from the
// chord" (symmetric zigzags produce equal deviations). Breaking a tie by "first one encountered
// while scanning" is NOT reversal-symmetric — scanning the same points forward vs backward
// finds a different point first, so an adjacent shape's own reverse-order run through this exact
// same physical run would pick a DIFFERENT anchor and end up simplified differently, producing a
// visible seam (confirmed empirically: this was the actual remaining cause of a small residual
// gap/overlap even after both douglasPeuckerRuns AND pinned-endpoint Chaikin were already
// correct). Breaking ties by the tied points' own coordinates instead of scan position fixes
// this, since a point's coordinates don't change based on which direction you're walking.
function douglasPeuckerOpen(points, epsilon){
  if(points.length<3) return points.slice();
  const a = points[0], b = points[points.length-1];
  let maxDist=-1, maxIdx=-1;
  const TIE_EPS = 1e-6;
  for(let i=1;i<points.length-1;i++){
    const d = pointLineDistance(points[i], a, b);
    if(d>maxDist+TIE_EPS){ maxDist=d; maxIdx=i; }
    else if(Math.abs(d-maxDist)<=TIE_EPS){
      const cur = points[maxIdx];
      if(points[i][0]<cur[0] || (points[i][0]===cur[0] && points[i][1]<cur[1])) maxIdx=i;
    }
  }
  if(maxDist<=epsilon) return [a,b];
  const left = douglasPeuckerOpen(points.slice(0,maxIdx+1), epsilon);
  const right = douglasPeuckerOpen(points.slice(maxIdx), epsilon);
  return left.slice(0,-1).concat(right);
}

// Closed-loop Douglas-Peucker fallback for the rare loop where EVERY edge faces the same
// neighbor identity (e.g. a territory that's a single enclave entirely surrounded by one other
// territory) — splitLoopIntoRuns() below can't find any identity change to anchor on, so there's
// no neighbor-transition point to use instead. Splitting at the loop's two most-distant points
// ("diameter") is safe here specifically because that split is a pure function of the point SET
// (not of which point the trace happened to start at, or which direction it walked), so the
// facing shape's own trace of this same physical loop picks the identical two anchor points too.
function douglasPeuckerLoop(loop, epsilon){
  if(loop.length<5) return loop.slice(); // too few points for a split to mean anything
  let i1=0, i2=1, maxD=-1;
  for(let i=0;i<loop.length;i++){
    for(let j=i+1;j<loop.length;j++){
      const d = distSq(loop[i], loop[j]);
      if(d>maxD){ maxD=d; i1=i; i2=j; }
    }
  }
  const arcA = loop.slice(i1, i2+1);
  const arcB = loop.slice(i2).concat(loop.slice(0, i1+1));
  const simpA = douglasPeuckerOpen(arcA, epsilon);
  const simpB = douglasPeuckerOpen(arcB, epsilon);
  return simpA.slice(0,-1).concat(simpB.slice(0,-1));
}

// Splits a traced loop into maximal runs of consecutive edges that all face the SAME outside
// identity (edgeIds[i] is the identity facing the edge from points[i] to points[(i+1)%n]).
// Each run is returned as an OPEN point array [transitionA, ..., transitionB] — the two ends are
// the corners where the neighbor identity actually changes, i.e. real "T-junction" points on the
// map (where 3+ territories/continents or empty space meet), not an arbitrary trace-order
// artifact. THIS is what makes shared-edge simplification consistent between two adjacent
// shapes: the run "my boundary facing neighbor B" and B's own run "my boundary facing me" cover
// the exact same physical points between the exact same two transition corners, so
// douglasPeuckerOpen() — a pure function of a fixed-endpoint point sequence — produces the same
// simplified curve on both sides no matter which shape's trace you started from (a farthest-pair
// split chosen independently per shape has no such guarantee, since each shape's own overall
// "diameter" generally has nothing to do with where ITS neighbors' boundaries happen to sit —
// confirmed by an actual gap/overlap measurement between two adjacent test shapes: ~11% raster
// area mismatched with an independent-anchor closed-loop split, ~0% with this neighbor-aware one).
// Returns null if every edge in the loop faces the same identity (no transition point exists at
// all) — the caller falls back to douglasPeuckerLoop() for that case.
function splitLoopIntoRuns(points, edgeIds){
  const n = edgeIds.length;
  let changeIdx = -1;
  for(let i=0;i<n;i++){ if(edgeIds[i]!==edgeIds[(i+n-1)%n]){ changeIdx=i; break; } }
  if(changeIdx===-1) return null;
  const runs = [];
  let runPts = [points[changeIdx]];
  let curId = edgeIds[changeIdx];
  for(let step=0; step<n; step++){
    const i = (changeIdx+step)%n;
    if(edgeIds[i]!==curId){
      runs.push(runPts);
      runPts = [points[i]];
      curId = edgeIds[i];
    }
    runPts.push(points[(i+1)%n]);
  }
  runs.push(runPts);
  return runs;
}

function traceAndSmoothCells(map, cellList, idFn){
  const cellSet = new Set(cellList.map(([c,r])=> c+'_'+r));
  const inSet = (c,r)=> cellSet.has(c+'_'+r);
  inSet.cells = cellList;
  const cs = map.cellSize;
  // Epsilon scales with cell size (not a fixed pixel value) so the same relative amount of
  // "unnecessary zigzag" gets removed regardless of a given map's resolution — a single-cell
  // staircase step typically deviates from its own smoothed diagonal by somewhere around half
  // a cell to a full cell, so 0.75 cells removes that noise without eating real, larger bends.
  const DP_EPSILON = cs*0.75;
  return traceMaskBoundary(inSet, idFn).map(({points, edgeIds}) => {
    const pixelPoints = points.map(([x,y])=>[x*cs,y*cs]);
    const runs = splitLoopIntoRuns(pixelPoints, edgeIds);
    if(runs){
      // Simplify AND smooth each run independently, with its own 2 endpoints pinned exactly
      // (chaikinSmoothOpen, not the closed-loop chaikinSmooth) — those endpoints are the
      // neighbor-transition corners an adjacent shape's own run shares, so they must come out
      // byte-identical on both sides, not independently rounded away by however much smoothing
      // each side's own unrelated neighboring run happens to pull them.
      const out = [];
      runs.forEach(run => {
        const dp = douglasPeuckerOpen(run, DP_EPSILON);
        const smoothed = chaikinSmoothOpen(dp, 2);
        out.push(...smoothed.slice(0,-1));
      });
      return out;
    }
    // Fallback (whole loop faces one uniform neighbor): safe to smooth as a normal closed loop
    // since douglasPeuckerLoop()'s farthest-pair anchors are a pure function of the shared point
    // SET, so a facing shape's own trace of this same loop picks the same anchors regardless of
    // where either trace started — see douglasPeuckerLoop()'s own comment.
    return chaikinSmooth(douglasPeuckerLoop(pixelPoints, DP_EPSILON), 2);
  });
}

// Cell-bounds-checked "what's at (c,r)" readers for the two idFn flavors below — out-of-map
// coordinates read as -1 (same "nothing here" sentinel newMap() fills cellTerritory with),
// since map.cellTerritory[r*cols+c] would otherwise silently alias into the wrong row/be
// out-of-range for a negative or overflowing c/r.
function territoryIdAt(map, c, r){
  if(c<0||r<0||c>=map.cols||r>=map.rows) return -1;
  return map.cellTerritory[cellIndex(map,c,r)];
}
function continentIdAt(map, c, r){
  const tid = territoryIdAt(map, c, r);
  if(tid<0) return -1;
  const t = map.territories[tid];
  return (t && t.continentId!=null) ? t.continentId : -1;
}

// Smoothed outer boundary (+ any water-hole boundaries) of a single territory, in pixel space,
// cached until invalidateBoundaryCache() drops it (see paintCell() below). idFn is by TERRITORY
// id here — see splitLoopIntoRuns() for why boundary simplification needs to know exactly which
// neighboring territory (not just "outside") faces each edge.
function getTerritoryBoundaryLoops(map, terrId){
  const t = map.territories[terrId];
  if(!t || t.cells.length===0) return [];
  if(!map._terrBoundaryCache) map._terrBoundaryCache = {};
  if(map._terrBoundaryCache[terrId]) return map._terrBoundaryCache[terrId];
  const loops = traceAndSmoothCells(map, t.cells, (c,r)=>territoryIdAt(map,c,r));
  map._terrBoundaryCache[terrId] = loops;
  return loops;
}

// Smoothed outer boundary of an entire continent (the union of all its member territories'
// cells) — used only for the thicker continent-outline overlay in continent view. idFn is by
// CONTINENT id here (not territory id) so an internal territory-territory seam within the same
// continent never looks like a "neighbor" to split a run on — only a genuinely different
// neighboring continent (or empty space) does.
function getContinentBoundaryLoops(map, contId){
  if(!map._contBoundaryCache) map._contBoundaryCache = {};
  if(map._contBoundaryCache[contId]) return map._contBoundaryCache[contId];
  const cellList = [];
  Object.values(map.territories).forEach(t=>{ if(t.continentId===contId) cellList.push(...t.cells); });
  const loops = cellList.length ? traceAndSmoothCells(map, cellList, (c,r)=>continentIdAt(map,c,r)) : [];
  map._contBoundaryCache[contId] = loops;
  return loops;
}

// Territory shape changes invalidate that territory's own cached boundary; continent shapes
// are unions of territories so any cell change could affect any continent's outline — cheap
// enough to just drop that whole (much smaller) cache rather than track it precisely.
function invalidateBoundaryCache(map, terrId){
  if(map._terrBoundaryCache) delete map._terrBoundaryCache[terrId];
  map._contBoundaryCache = {};
}

function paintCell(map, c, r, terrId){
  if(!inBounds(map,c,r)) return;
  const idx = cellIndex(map,c,r);
  const old = map.cellTerritory[idx];
  if(old === terrId) return;
  if(old !== -1 && map.territories[old]){
    const t = map.territories[old];
    const i = t.cells.findIndex(cc=>cc[0]===c&&cc[1]===r);
    if(i>=0) t.cells.splice(i,1);
    invalidateBoundaryCache(map, old);
  }
  map.cellTerritory[idx] = terrId;
  if(terrId !== -1 && map.territories[terrId]){
    map.territories[terrId].cells.push([c,r]);
    invalidateBoundaryCache(map, terrId);
  }
}

function bucketFill(map, c, r, newId){
  const idx = cellIndex(map,c,r);
  const target = map.cellTerritory[idx];
  if(target === newId) return;
  const stack = [[c,r]];
  const visited = new Set();
  while(stack.length){
    const [cc,rr] = stack.pop();
    const key = cc+","+rr;
    if(visited.has(key)) continue;
    visited.add(key);
    if(!inBounds(map,cc,rr)) continue;
    if(map.cellTerritory[cellIndex(map,cc,rr)] !== target) continue;
    paintCell(map,cc,rr,newId);
    stack.push([cc+1,rr],[cc-1,rr],[cc,rr+1],[cc,rr-1]);
  }
}

function recomputeGraph(map){
  // neighbors + centroids
  Object.values(map.territories).forEach(t=>{ t.neighbors = new Set(); t.centroid={x:0,y:0}; });
  for(let r=0;r<map.rows;r++){
    for(let c=0;c<map.cols;c++){
      const id = map.cellTerritory[cellIndex(map,c,r)];
      if(id===-1) continue;
      // right neighbor
      if(c+1<map.cols){
        const id2 = map.cellTerritory[cellIndex(map,c+1,r)];
        if(id2!==-1 && id2!==id){ map.territories[id]?.neighbors.add(id2); map.territories[id2]?.neighbors.add(id); }
      }
      // down neighbor
      if(r+1<map.rows){
        const id2 = map.cellTerritory[cellIndex(map,c,r+1)];
        if(id2!==-1 && id2!==id){ map.territories[id]?.neighbors.add(id2); map.territories[id2]?.neighbors.add(id); }
      }
    }
  }
  // World wrap: the last column/row also touches the first one across the seam.
  const linkAcrossSeam = (idxA, idxB)=>{
    const a = map.cellTerritory[idxA], b = map.cellTerritory[idxB];
    if(a===-1 || b===-1 || a===b) return;
    map.territories[a]?.neighbors.add(b); map.territories[b]?.neighbors.add(a);
  };
  if(map.wrapX && map.cols>2) for(let r=0;r<map.rows;r++) linkAcrossSeam(cellIndex(map,map.cols-1,r), cellIndex(map,0,r));
  if(map.wrapY && map.rows>2) for(let c=0;c<map.cols;c++) linkAcrossSeam(cellIndex(map,c,map.rows-1), cellIndex(map,c,0));
  // "centroid" is the territory's anchor point — where its army badge sits and where attack/
  // fortify arrows start and end. It's the deepest cell (see territoryPoleCell), not the plain
  // average position, since the average of a concave territory can land on its edge or outside it.
  Object.values(map.territories).forEach(t=>{
    if(t.cells.length===0){ t.centroid={x:-1,y:-1}; return; }
    const [pc,pr] = territoryPoleCell(t.cells);
    t.centroid = { x: (pc+0.5)*map.cellSize, y: (pr+0.5)*map.cellSize };
  });
}

/* ---------------- Portrait auto-rotation ----------------
   The map is purely grid-based (cellTerritory + per-territory cell lists), so rotating it 90° is
   just a coordinate remap — border/centroid rendering, click hit-testing and AI/combat logic all
   already work generically off of map.cols/map.rows/cellTerritory, with no orientation-specific
   code of their own, so none of that needs touching. Adjacency is also rotation-invariant (two
   cells don't stop being neighbors just because the grid turned), so only cell coordinates and
   the derived centroid/pole-cell actually need recomputing — done here via the same
   recomputeGraph() every other map-construction path already uses.
   One 90° clockwise step: (c,r) in a cols×rows grid -> (rows-1-r, c) in the resulting rows×cols
   grid. See maybeRotateMapForPortrait() in 06-render-game.js for when/why this gets called, and
   unrotateMapData() below for undoing it (always 3 more of these steps = 270° = -90°). */
function rotateMapData90CW(map){
  const oldCols = map.cols, oldRows = map.rows;
  const newCols = oldRows, newRows = oldCols;
  const rotated = newMap(newCols, newRows, map.name);
  rotated.cellSize = map.cellSize;
  // (c,r) -> (rows-1-r, c): old columns become new rows, so a left/right seam becomes top/bottom.
  rotated.wrapX = !!map.wrapY; rotated.wrapY = !!map.wrapX;
  Object.values(map.territories).forEach(t=>{
    rotated.territories[t.id] = {id:t.id, name:t.name, continentId:t.continentId, color:t.color, cells:[], neighbors:new Set(), centroid:{x:0,y:0}};
  });
  Object.values(map.continents).forEach(c=>{
    rotated.continents[c.id] = {id:c.id, name:c.name, color:c.color, bonus:c.bonus};
  });
  for(let r=0;r<oldRows;r++){
    for(let c=0;c<oldCols;c++){
      const id = map.cellTerritory[r*oldCols+c];
      if(id===-1) continue;
      const nc = oldRows-1-r, nr = c;
      rotated.cellTerritory[nr*newCols+nc] = id;
      rotated.territories[id].cells.push([nc,nr]);
    }
  }
  rotated.nextTerrId = map.nextTerrId;
  rotated.nextContId = map.nextContId;
  recomputeGraph(rotated);
  return rotated;
}
// Rotating 3 more times (270° CW = -90°) undoes a single rotateMapData90CW() call exactly —
// the grid is all integer coordinates, so this round-trips back to the identical map, not just an
// approximation. Tagged with _rotatedFor90 (set by maybeRotateMapForPortrait()) rather than
// tracked in a separate "original map" variable, so the one map object is always self-describing
// and nothing needs to remember to reset a side variable whenever a genuinely new map is loaded.
function unrotateMapData(map){
  if(!map._rotatedFor90) return map;
  return rotateMapData90CW(rotateMapData90CW(rotateMapData90CW(map)));
}

/* ---------------- Procedural random map generator ---------------- */
/* Generate an organic water mask (1 = water, 0 = land) covering roughly waterRatio of the grid,
   grown from a handful of random blobs so coastlines look natural rather than speckled noise. */
/* Connected components of the territory adjacency graph. Water always breaks graph edges
   (see recomputeGraph), so each component is exactly one contiguous landmass/island. */
function findConnectedComponents(map){
  const seen = new Set();
  const comps = [];
  Object.keys(map.territories).map(Number).forEach(start=>{
    if(seen.has(start)) return;
    const comp = [];
    const stack=[start];
    seen.add(start);
    while(stack.length){
      const cur = stack.pop();
      comp.push(cur);
      map.territories[cur].neighbors.forEach(n=>{
        if(!seen.has(n)){ seen.add(n); stack.push(n); }
      });
    }
    comps.push(comp);
  });
  return comps;
}

/* Any whole landmass (one territory or a cluster of several, all cut off from the rest of the
   map by water) can never be attacked, reinforced into, or attacked FROM by anyone else — it's
   a dead island. Carve a thin land bridge through water from that island to the nearest other
   landmass so the entire map ends up as a single connected graph. Repeats since merging two
   components can occasionally still leave others isolated, and a single guarded pass keeps
   bridging until only one component remains (or we give up after enough tries). */
function ensureNoIsolatedTerritories(map){
  let guard=0;
  while(guard++<50){
    const comps = findConnectedComponents(map);
    if(comps.length<=1) break;
    // Bridge every component except the largest one out towards the rest of the map — the
    // largest is treated as "mainland" so smaller islands connect back to it (directly or,
    // after a later pass, transitively through another island they land next to).
    comps.sort((a,b)=> b.length-a.length);
    for(let i=1;i<comps.length;i++){
      bridgeComponentOut(map, comps[i]);
    }
    recomputeGraph(map);
  }
}

function bridgeComponentOut(map, compTerrIds){
  const compSet = new Set(compTerrIds);
  const cols = map.cols;
  const visited = new Set();
  const queue = [];
  compTerrIds.forEach(tid=>{
    const t = map.territories[tid];
    if(!t) return;
    t.cells.forEach(([c,r])=>{
      const idx = r*cols+c;
      if(!visited.has(idx)){ visited.add(idx); queue.push({c,r,parent:null,ownerTid:tid}); }
    });
  });
  // BFS outward from every cell of every territory in this component, travelling only through
  // water, until we reach a cell that belongs to a territory OUTSIDE this component.
  let qi = 0, target = null;
  while(qi<queue.length && !target){
    const cur = queue[qi++];
    for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
      const nc=cur.c+dc, nr=cur.r+dr;
      if(!inBounds(map,nc,nr)) continue;
      const idx = nr*cols+nc;
      if(visited.has(idx)) continue;
      const cellTid = map.cellTerritory[idx];
      if(cellTid!==-1 && !compSet.has(cellTid)){ target = {c:nc,r:nr,parent:cur,srcTid:cur.ownerTid}; break; }
      if(cellTid===-1){ visited.add(idx); queue.push({c:nc,r:nr,parent:cur,ownerTid:cur.ownerTid}); }
    }
  }
  if(!target) return; // whole map is this one component — nothing to bridge to
  // walk back from the target's parent (the water cells forming the shortest path) and claim
  // them as the source territory's own land, stopping once back at that territory's own cells.
  const tid = target.srcTid;
  let cur = target.parent;
  while(cur && map.cellTerritory[cur.r*cols+cur.c] !== tid){
    paintCell(map, cur.c, cur.r, tid);
    cur = cur.parent;
  }
}

// Lays down a jagged coastal band of water hugging all 4 edges of the grid, with an
// organic (random-walk + smoothing), varying depth per edge column/row instead of a
// straight-ruled ring — so territories that grow up against it later trace a natural-looking
// coastline rather than following the map's rectangular bounding box. Runs before territories
// (and before the interior lake blobs below) are generated, and independently of the
// water-ratio slider, since it's about edge shape rather than total lake area.
// wrapX: the left/right edges are a seam (world wrap), not a coast — no band there, and the
// top/bottom bands are made continuous across the seam so the coastline doesn't visibly jump.
function applyCoastalBand(water, cols, rows, wrapX){
  const minDim = Math.min(cols, rows);
  const minDepth = clamp(Math.round(minDim*0.06), 1, 3);
  const maxDepth = clamp(Math.round(minDim*0.18), minDepth+2, Math.max(minDepth+2, Math.floor(minDim/3)));
  function walkDepths(length, circular){
    const raw = new Array(length);
    let d = minDepth + rand(maxDepth-minDepth+1);
    for(let i=0;i<length;i++){ d = clamp(d + rand(3)-1, minDepth, maxDepth); raw[i] = d; }
    if(circular && length>1){
      // tilt the walk so its last step lands back next to its first — continuous across the seam
      const drift = raw[length-1]-raw[0];
      for(let i=0;i<length;i++) raw[i] = clamp(Math.round(raw[i] - drift*i/(length-1)), minDepth, maxDepth);
    }
    // two smoothing passes turn the per-step jitter into gentle, coastline-like curves
    let smoothed = raw;
    for(let pass=0; pass<2; pass++){
      const src = smoothed, next = new Array(length);
      for(let i=0;i<length;i++){
        let sum=0, cnt=0;
        for(let k=-2;k<=2;k++){
          let j=i+k;
          if(circular) j=(j+length)%length;
          if(j>=0 && j<length){ sum+=src[j]; cnt++; }
        }
        next[i] = Math.round(sum/cnt);
      }
      smoothed = next;
    }
    return smoothed;
  }
  const topDepth = walkDepths(cols, wrapX), bottomDepth = walkDepths(cols, wrapX);
  for(let c=0;c<cols;c++){
    for(let r=0;r<topDepth[c];r++) water[r*cols+c]=1;
    for(let r=0;r<bottomDepth[c];r++) water[(rows-1-r)*cols+c]=1;
  }
  if(wrapX) return;
  const leftDepth = walkDepths(rows), rightDepth = walkDepths(rows);
  for(let r=0;r<rows;r++){
    for(let c=0;c<leftDepth[r];c++) water[r*cols+c]=1;
    for(let c=0;c<rightDepth[r];c++) water[r*cols+(cols-1-c)]=1;
  }
}

function generateWaterMask(cols, rows, waterRatio, spread, wrapX){
  const total = cols*rows;
  const water = new Uint8Array(total);
  applyCoastalBand(water, cols, rows, wrapX);
  const targetWater = Math.round(total*clamp(waterRatio,0,0.7));
  if(targetWater<=0) return water;
  // spread (0-1): how scattered the water is. At 0, few big blobs grow into large lakes/seas
  // (the original behavior); at 1, the same total water area is seeded from many more, smaller
  // blobs with a lower per-cell fill chance so the coastline comes out raggeder and more spread
  // out across the map instead of piling into 1-2 big clumps.
  const s = clamp(spread===undefined?0.4:spread, 0, 1);
  const baseBlobs = clamp(Math.round(Math.sqrt(total)/9), 1, 6);
  const maxBlobs = Math.max(baseBlobs, Math.round(total/120));
  let numBlobs = clamp(Math.round(baseBlobs + s*(maxBlobs-baseBlobs)), 1, maxBlobs);
  // Cap blob count so a low waterRatio can't stretch too little water across too many seeds —
  // each blob is kept at least a meaningful fraction of an average territory's footprint,
  // otherwise every blob barely grows past its own seed cell and the map ends up speckled with
  // tiny decorative ponds instead of a few lakes/straits large enough to matter.
  const minBlobSize = Math.max(8, Math.round(computeCellsPerTerritory(cols)*0.25));
  numBlobs = Math.min(numBlobs, Math.max(1, Math.floor(targetWater/minBlobSize)));
  const fillProb = 0.88 - s*0.33;
  const allCells = [];
  for(let r=0;r<rows;r++) for(let c=0;c<cols;c++) allCells.push([c,r]);
  const seeds = shuffle(allCells).slice(0, numBlobs);
  let frontier = seeds.map(([c,r])=>({c,r}));
  let count = 0;
  seeds.forEach(([c,r])=>{ const idx=r*cols+c; if(!water[idx]){ water[idx]=1; count++; } });
  let guard=0;
  while(count<targetWater && guard++<20000){
    if(frontier.length===0){
      // stuck (surrounded) - seed a fresh blob elsewhere to keep growing
      const remaining = allCells.filter(([c,r])=>!water[r*cols+c]);
      if(remaining.length===0) break;
      const [c,r] = randChoice(remaining);
      water[r*cols+c]=1; count++;
      frontier = [{c,r}];
      continue;
    }
    frontier = shuffle(frontier);
    const next = [];
    for(const {c,r} of frontier){
      if(count>=targetWater) break;
      const dirs = shuffle([[1,0],[-1,0],[0,1],[0,-1]]);
      for(const [dc,dr] of dirs){
        if(count>=targetWater) break;
        let nc=c+dc; const nr=r+dr;
        if(wrapX) nc=(nc+cols)%cols; // lakes/straits can flow across the seam
        if(nc<0||nc>=cols||nr<0||nr>=rows) continue;
        const idx = nr*cols+nc;
        if(water[idx]) continue;
        if(random()<fillProb){ water[idx]=1; count++; next.push({c:nc,r:nr}); }
      }
    }
    frontier = next;
  }
  return water;
}

// Grid resolution is fixed and viewport-independent: always fine enough that territory
// boundaries have plenty of points for the Chaikin smoothing in getTerritoryBoundaryLoops() to
// round into organic-looking coastlines, instead of the old approach of shrinking cols/rows to
// hit a target on-screen size directly — a coarse mobile grid (e.g. 16 rows) gives each
// territory only a handful of boundary cells to work with, so it comes out blocky no matter how
// well the target px size was tuned. 150 was picked from benchmarking generateRandomMap() +
// boundary computation together: a 300x150 grid (2:1 aspect) generates in well under 300ms even
// under simulated 4x CPU throttling, so it stays imperceptible on slow devices.
const MIN_GRID_DIM = 150;

// How many of those fixed-resolution cells go into one territory is what actually depends on
// the viewport: on-screen px per cell shrinks as the physical screen shrinks, so more cells are
// needed per territory on a small phone to keep its footprint near AVG_TERRITORY_TARGET_PX.
function computeCellsPerTerritory(cols){
  const availW = estimateCanvasWidth();
  const cellPx = availW/cols;
  return Math.max(8, Math.round((AVG_TERRITORY_TARGET_PX/cellPx)**2));
}

// Territory/continent counts for a random map of a given grid size — kept as one shared formula
// so every call site (quick play, editor's initial map, editor's "Ngẫu nhiên" button) derives
// numCont with enough headroom above the min-4-territories-per-continent floor that
// reassignContinents() enforces below, instead of each guessing its own fixed continent count
// independent of how many territories the grid actually ends up with.
function deriveMapGenCounts(cols, rows){
  const cellsPerTerritory = computeCellsPerTerritory(cols);
  const numTerr = Math.max(8, Math.round(cols*rows/cellsPerTerritory));
  const numCont = clamp(Math.round(numTerr/6), 2, 8);
  return { numTerr, numCont };
}

// Full plan for a freshly random-generated map: grid size is fixed at MIN_GRID_DIM on its
// shorter side (aspect-matched to the current viewport so the grid isn't oddly cropped), and
// numTerr/numCont are derived from that grid via deriveMapGenCounts(). Only used at generation
// time — an already-generated/saved map keeps its own grid regardless of what device later
// opens it.
// Grid shape is always square, regardless of the viewport's actual aspect ratio — a consistent,
// predictable map shape rather than one that changes with whatever window the map happens to be
// generated in. The side is picked to keep the same area as the old 3:2 grid (225x150), so a
// generated map still comes out with about the same number of territories.
const MAP_GEN_SIDE = Math.round(Math.sqrt(MIN_GRID_DIM*MIN_GRID_DIM*3/2)); // 184

// A global map is square; a flat one keeps the old 3:2 landscape grid.
function computeMapGenPlan(wrap){
  if(!wrap) return { ...landscapeGenPlan() };
  const rows = MAP_GEN_SIDE, cols = MAP_GEN_SIDE;
  // Territory/continent counts as for the old 3:2 grid of the same area, so switching to the
  // square shape didn't change how many territories a game has (deriveMapGenCounts() scales with
  // rows/cols, so the square grid on its own would ask for ~50% more).
  const { numTerr, numCont } = deriveMapGenCounts(Math.round(MIN_GRID_DIM*3/2), MIN_GRID_DIM);
  return { cols, rows, numTerr, numCont };
}
function landscapeGenPlan(){
  const rows = MIN_GRID_DIM, cols = Math.round(MIN_GRID_DIM*3/2);
  const { numTerr, numCont } = deriveMapGenCounts(cols, rows);
  return { cols, rows, numTerr, numCont };
}

// Flood-cell-fills the connected land components of a water mask and turns any component
// smaller than minCells back into water. At a fine grid resolution (MIN_GRID_DIM), the jagged
// coastal band and interior lake blobs routinely pinch off tiny stray slivers of land — without
// this cleanup, generateRandomMap()'s "claim leftover unclaimed land as its own territory"
// fallback below turns every one of those slivers into a full, separately-named 1-3 cell
// territory, flooding the map with unplayable micro-territories.
function submergeTinyLandIslands(water, cols, rows, minCells, wrapX){
  const total = cols*rows;
  const visited = new Uint8Array(total);
  for(let start=0; start<total; start++){
    if(water[start] || visited[start]) continue;
    const comp = [start];
    visited[start] = 1;
    for(let qi=0; qi<comp.length; qi++){
      const idx = comp[qi], c = idx%cols, r = (idx/cols)|0;
      for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
        let nc=c+dc; const nr=r+dr;
        if(wrapX) nc=(nc+cols)%cols; // land touching both edges is ONE landmass across the seam
        if(nc<0||nc>=cols||nr<0||nr>=rows) continue;
        const nidx = nr*cols+nc;
        if(!water[nidx] && !visited[nidx]){ visited[nidx]=1; comp.push(nidx); }
      }
    }
    if(comp.length < minCells) comp.forEach(idx=> water[idx]=1);
  }
}

/* ---------------- Territory partitioning: "every territory fits 3 army badges" ----------------
   Random maps partition land into territories so that EVERY territory can hold 3 of the
   fixed-size army badges (ARMY_BADGE_RADIUS, 01-utils.js) side by side without them overlapping
   each other or poking out past the territory's edge — a hard guarantee, checked exactly per
   territory (territoryFitsBadges below), not just a cell-count heuristic.

   Pipeline (see generateRandomMap):
     1. Farthest-point seeds + a few rounds of Lloyd relaxation over a noise-weighted geodesic
        Voronoi on the land cells -> compact, similarly-sized, organically-edged regions. This
        is what makes nearly every territory pass the check on its own, instead of the old
        "random BFS race" which left lots of cramped leftovers that then had to be rescued.
     2. repairUnfitTerritories: whatever still fails is merged into a neighbor that passes
        (a superset of a passing territory always passes too, so this can't cascade), or sunk
        into the sea if it's an island too small to ever pass.
     3. splitToTargetCount: gives back the territories step 2 merged away by splitting the
        largest ones in two — only when BOTH halves pass the same check. */

// Exact squared Euclidean distance transform (Felzenszwalb & Huttenlocher), 1D pass.
function edt1d(f, n, d, v, z){
  let k = 0; v[0] = 0; z[0] = -Infinity; z[1] = Infinity;
  for(let q=1; q<n; q++){
    let s = ((f[q]+q*q)-(f[v[k]]+v[k]*v[k]))/(2*q-2*v[k]);
    while(s<=z[k]){ k--; s = ((f[q]+q*q)-(f[v[k]]+v[k]*v[k]))/(2*q-2*v[k]); }
    k++; v[k] = q; z[k] = s; z[k+1] = Infinity;
  }
  k = 0;
  for(let q=0; q<n; q++){
    while(z[k+1]<q) k++;
    d[q] = (q-v[k])*(q-v[k]) + f[v[k]];
  }
}

// Squared distance (in cells, center to center) from every cell of `cells` to the nearest cell
// NOT in `cells`, computed over the cells' bounding box padded by 1 (so every row/column has an
// outside cell to measure against). d2 is indexed (r-minR)*w + (c-minC); outside cells are 0.
function territoryEDT(cells){
  let minC=Infinity, maxC=-Infinity, minR=Infinity, maxR=-Infinity;
  for(const [c,r] of cells){ if(c<minC)minC=c; if(c>maxC)maxC=c; if(r<minR)minR=r; if(r>maxR)maxR=r; }
  minC--; minR--; maxC++; maxR++;
  const w = maxC-minC+1, h = maxR-minR+1;
  const d2 = new Float64Array(w*h);
  const BIG = 1e12;
  for(const [c,r] of cells) d2[(r-minR)*w + (c-minC)] = BIG;
  const n = Math.max(w,h);
  const f = new Float64Array(n), d = new Float64Array(n), v = new Int32Array(n), z = new Float64Array(n+1);
  for(let x=0; x<w; x++){
    for(let y=0; y<h; y++) f[y] = d2[y*w+x];
    edt1d(f, h, d, v, z);
    for(let y=0; y<h; y++) d2[y*w+x] = d[y];
  }
  for(let y=0; y<h; y++){
    for(let x=0; x<w; x++) f[x] = d2[y*w+x];
    edt1d(f, w, d, v, z);
    for(let x=0; x<w; x++) d2[y*w+x] = d[x];
  }
  return {minC, minR, w, h, d2};
}

// Distance from a cell center to the nearest outside cell CENTER overstates how far the badge can
// reach before touching the territory's actual edge (half a cell, more on diagonals), and the
// Douglas-Peucker/Chaikin outline smoothing can shave a bit more off corners — so every badge
// needs this much extra room on top of its own radius.
const BADGE_FIT_MARGIN_CELLS = 1;

// True if 3 army badges fit inside `cells` without overlapping each other or crossing its edge.
// Valid badge centers are cells at least (badge radius + margin) from the edge; we need 3 of them
// pairwise >= 1 badge diameter apart. Fast path: if the deepest point has room for an equilateral
// triangle of badge centers around it (clearance is 1-Lipschitz, so each vertex keeps enough),
// it passes outright. Otherwise a few greedy farthest-point triples are tried — this can only
// ever under-report a fit (a false "no" just means one extra merge), never over-report one.
// Deterministic for a given cell list.
function territoryFitsBadges(map, cells){
  if(cells.length<3) return false;
  const rC = ARMY_BADGE_RADIUS/map.cellSize;
  const need = rC + BADGE_FIT_MARGIN_CELLS;
  const e = territoryEDT(cells);
  const need2 = need*need;
  const pts = [];
  let best2 = 0;
  for(let i=0; i<e.d2.length; i++){
    const v2 = e.d2[i];
    if(v2>=need2) pts.push(i);
    if(v2>best2) best2 = v2;
  }
  if(pts.length<3) return false;
  const tri = need + 2*rC/Math.sqrt(3);
  if(best2 >= tri*tri) return true;
  const sep2 = (2*rC)*(2*rC);
  const xs = pts.map(i=> i%e.w), ys = pts.map(i=> (i/e.w)|0);
  const dist2 = (a,b)=> (xs[a]-xs[b])**2 + (ys[a]-ys[b])**2;
  const farthestFrom = (a)=>{ let bi=0, bd=-1; for(let i=0;i<pts.length;i++){ const dd=dist2(a,i); if(dd>bd){ bd=dd; bi=i; } } return bi; };
  for(let attempt=0; attempt<8; attempt++){
    // deterministic starts, so re-checking the same territory always gives the same answer
    const start = Math.floor(attempt*pts.length/8);
    const a = farthestFrom(start), c = farthestFrom(a);
    if(dist2(a,c)<sep2) return false; // even the two farthest-apart valid centers are too close
    let b=-1, bd=-1;
    for(let i=0;i<pts.length;i++){ const dd = Math.min(dist2(a,i), dist2(c,i)); if(dd>bd){ bd=dd; b=i; } }
    if(bd>=sep2) return true;
  }
  return false;
}

// The "pole of inaccessibility" of a territory: its deepest cell (farthest from any edge), ties
// broken toward the plain average position. Used as the territory's badge anchor (see
// recomputeGraph) — the average position of a concave or crescent-shaped territory can sit right
// on its edge or even outside it, which is exactly where a badge doesn't fit.
function territoryPoleCell(cells){
  const e = territoryEDT(cells);
  let mx=0, my=0;
  for(const [c,r] of cells){ mx+=c; my+=r; }
  mx/=cells.length; my/=cells.length;
  let bestIdx=-1, bestD=-1, bestTie=Infinity;
  for(let i=0;i<e.d2.length;i++){
    const v2 = e.d2[i];
    if(v2<=0) continue;
    const c = (i%e.w)+e.minC, r = ((i/e.w)|0)+e.minR;
    const tie = (c-mx)**2 + (r-my)**2;
    if(v2>bestD || (v2===bestD && tie<bestTie)){ bestD=v2; bestTie=tie; bestIdx=i; }
  }
  return [(bestIdx%e.w)+e.minC, ((bestIdx/e.w)|0)+e.minR];
}

// Smooth random field in [1-amp, 1+amp] (bilinear-interpolated coarse random grid) used as a
// per-cell step cost, so Voronoi region boundaries wander organically instead of running in the
// dead-straight lines a plain distance metric gives.
function makeNoiseWeight(cols, rows, step, amp){
  const gw = Math.ceil(cols/step)+2, gh = Math.ceil(rows/step)+2;
  const g = new Float64Array(gw*gh);
  for(let i=0;i<g.length;i++) g[i] = random()*2-1;
  const w = new Float64Array(cols*rows);
  const smooth = t=> t*t*(3-2*t);
  for(let r=0;r<rows;r++){
    const gy = r/step, y0 = Math.floor(gy), fy = smooth(gy-y0);
    for(let c=0;c<cols;c++){
      const gx = c/step, x0 = Math.floor(gx), fx = smooth(gx-x0);
      const a = g[y0*gw+x0], b = g[y0*gw+x0+1], cc = g[(y0+1)*gw+x0], d = g[(y0+1)*gw+x0+1];
      const val = (a*(1-fx)+b*fx)*(1-fy) + (cc*(1-fx)+d*fx)*fy;
      w[r*cols+c] = 1 + amp*val;
    }
  }
  return w;
}

const NB_DX = [1,-1,0,0,1,1,-1,-1], NB_DY = [0,0,1,-1,1,-1,1,-1];
const NB_LEN = [1,1,1,1,Math.SQRT2,Math.SQRT2,Math.SQRT2,Math.SQRT2];

// Multi-source Dijkstra over the cells where mask[idx] is set: each cell gets the index of the
// seed nearest to it along paths that stay inside the mask (so regions never reach across water).
// Diagonal steps only where both cells they cut past are in the mask too. `offsets` (optional,
// per seed) gives a seed a head start — an additively-weighted Voronoi, which is how the
// generator lets a too-small region claim more land from its neighbors. Returns Int32Array
// labels (-1 = unreachable from every seed).
// Called dozens of times per generated map, so the heap is inlined over typed arrays rather than
// going through a generic heap object — this loop is most of the generator's run time.
function weightedVoronoi(cols, rows, mask, seedIdxs, weight, offsets){
  const n = cols*rows;
  const dist = new Float64Array(n).fill(Infinity);
  const label = new Int32Array(n).fill(-1);
  let cap = 4096, size = 0;
  let hk = new Float64Array(cap), hv = new Int32Array(cap);
  const push = (key, val)=>{
    if(size===cap){
      cap *= 2;
      const nk = new Float64Array(cap); nk.set(hk); hk = nk;
      const nv = new Int32Array(cap); nv.set(hv); hv = nv;
    }
    let i = size++;
    while(i>0){ const p=(i-1)>>1; if(hk[p]<=key) break; hk[i]=hk[p]; hv[i]=hv[p]; i=p; }
    hk[i]=key; hv[i]=val;
  };
  for(let i=0;i<seedIdxs.length;i++){
    const s = seedIdxs[i], d0 = offsets ? -offsets[i] : 0;
    if(d0<dist[s]){ dist[s]=d0; label[s]=i; push(d0,s); }
  }
  while(size>0){
    const idx = hv[0], d = hk[0];
    const lk = hk[--size], lv = hv[size];
    if(size>0){
      let i=0;
      for(;;){
        const l=2*i+1; if(l>=size) break;
        const r=l+1, m=(r<size && hk[r]<hk[l])?r:l;
        if(hk[m]>=lk) break;
        hk[i]=hk[m]; hv[i]=hv[m]; i=m;
      }
      hk[i]=lk; hv[i]=lv;
    }
    if(d>dist[idx]) continue;
    const c = idx%cols, r = (idx/cols)|0, w0 = weight[idx], lab = label[idx];
    for(let k=0;k<8;k++){
      const nc=c+NB_DX[k], nr=r+NB_DY[k];
      if(nc<0||nc>=cols||nr<0||nr>=rows) continue;
      const nidx = nr*cols+nc;
      if(!mask[nidx]) continue;
      if(k>=4 && (!mask[r*cols+nc] || !mask[nr*cols+c])) continue;
      const nd = d + NB_LEN[k]*0.5*(w0+weight[nidx]);
      if(nd<dist[nidx]){ dist[nidx]=nd; label[nidx]=lab; push(nd,nidx); }
    }
  }
  return label;
}

// Greedy farthest-point sampling of k cells out of `cellIdxs` (flat indices) — spreads seeds
// evenly over the land instead of leaving 2 of them side by side.
function farthestPointSeeds(cols, cellIdxs, k){
  if(cellIdxs.length===0) return [];
  const minD = new Float64Array(cellIdxs.length).fill(Infinity);
  const seeds = [];
  let next = rand(cellIdxs.length);
  while(seeds.length<k && seeds.length<cellIdxs.length){
    const s = cellIdxs[next]; seeds.push(s);
    const sc = s%cols, sr = (s/cols)|0;
    let bi = -1, bd = -1;
    for(let i=0;i<cellIdxs.length;i++){
      const idx = cellIdxs[i], dd = (idx%cols-sc)**2 + (((idx/cols)|0)-sr)**2;
      if(dd<minD[i]) minD[i] = dd;
      if(minD[i]>bd){ bd = minD[i]; bi = i; }
    }
    if(bd<=0) break;
    next = bi;
  }
  return seeds;
}

// One Lloyd step: move every seed to the cell of its own region nearest that region's average
// position (staying on a real cell of the region, so it never lands in water).
function lloydMoveSeeds(cols, cellIdxs, label, seeds){
  const k = seeds.length;
  const sx = new Float64Array(k), sy = new Float64Array(k), cnt = new Float64Array(k);
  for(const idx of cellIdxs){ const l = label[idx]; if(l<0) continue; sx[l]+=idx%cols; sy[l]+=(idx/cols)|0; cnt[l]++; }
  const bestD = new Float64Array(k).fill(Infinity);
  const moved = seeds.slice();
  for(const idx of cellIdxs){
    const l = label[idx]; if(l<0 || cnt[l]===0) continue;
    const dd = (idx%cols - sx[l]/cnt[l])**2 + (((idx/cols)|0) - sy[l]/cnt[l])**2;
    if(dd<bestD[l]){ bestD[l]=dd; moved[l]=idx; }
  }
  return moved;
}

// Lloyd relaxation: repeatedly partition, then recenter every seed in its region. A few rounds
// turn an uneven first partition into compact, roughly equal-area regions. Returns the labels.
function relaxedPartition(cols, rows, mask, cellIdxs, seeds, weight, rounds){
  let label = weightedVoronoi(cols, rows, mask, seeds, weight);
  for(let it=0; it<rounds; it++){
    seeds = lloydMoveSeeds(cols, cellIdxs, label, seeds);
    label = weightedVoronoi(cols, rows, mask, seeds, weight);
  }
  return label;
}

// Partition the land into `k` regions that (as far as the land allows) each fit 3 badges:
// Lloyd-relaxed noisy Voronoi for compact shapes, then a balancing loop — every region that
// still fails gets a bigger head start (offset) and the partition is redone, so cramped regions
// (typically squeezed against the coast) grow into their roomier neighbors instead of being
// merged away. Whatever still fails after this is handled by repairUnfitTerritories().
function balancedFitPartition(map, mask, landIdxs, k, weight){
  const {cols, rows} = map;
  let seeds = farthestPointSeeds(cols, landIdxs, k);
  const offsets = new Float64Array(seeds.length);
  // Most regions don't change between balancing rounds (only the ones next to a growing region
  // do) — a cheap signature of each region's cells skips re-checking the unchanged ones.
  const lastSig = new Array(seeds.length).fill(null), lastFit = new Array(seeds.length).fill(false);
  let label = null;
  for(let it=0; it<25; it++){
    label = weightedVoronoi(cols, rows, mask, seeds, weight, offsets);
    if(it<5){ seeds = lloydMoveSeeds(cols, landIdxs, label, seeds); continue; }
    enforceConnectedRegions(cols, rows, landIdxs, label);
    const cellsOf = seeds.map(()=>[]), sig = seeds.map(()=>0);
    for(const idx of landIdxs){
      const l=label[idx]; if(l<0) continue;
      cellsOf[l].push([idx%cols,(idx/cols)|0]);
      sig[l] = (sig[l]*31 + idx) % 2147483647;
    }
    let anyFail = false;
    cellsOf.forEach((cells,i)=>{
      if(!cells.length) return;
      const s = cells.length+':'+sig[i];
      if(s!==lastSig[i]){ lastSig[i]=s; lastFit[i]=territoryFitsBadges(map, cells); }
      if(!lastFit[i]){ offsets[i] += 2; anyFail = true; }
    });
    if(!anyFail) return label;
  }
  enforceConnectedRegions(cols, rows, landIdxs, label);
  return label;
}

// A region can come out of the partition in more than one 4-connected piece (two regions
// pinching through a diagonal gap, say) — the game's adjacency is 4-directional, so each region
// keeps only its biggest piece and every smaller stray piece is handed to whichever other region
// borders it most.
function enforceConnectedRegions(cols, rows, cellIdxs, label){
  for(let pass=0; pass<10; pass++){
    const comp = new Int32Array(cols*rows).fill(-1);
    const comps = [];
    for(const start of cellIdxs){
      if(label[start]<0 || comp[start]!==-1) continue;
      const id = comps.length, l = label[start], cells=[start];
      comp[start] = id;
      for(let qi=0; qi<cells.length; qi++){
        const idx=cells[qi], c=idx%cols, r=(idx/cols)|0;
        for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
          const nc=c+dc, nr=r+dr;
          if(nc<0||nc>=cols||nr<0||nr>=rows) continue;
          const nidx=nr*cols+nc;
          if(comp[nidx]===-1 && label[nidx]===l){ comp[nidx]=id; cells.push(nidx); }
        }
      }
      comps.push({l, cells});
    }
    const biggest = {};
    comps.forEach((cp,i)=>{ if(biggest[cp.l]===undefined || cp.cells.length>comps[biggest[cp.l]].cells.length) biggest[cp.l]=i; });
    let changed = false;
    comps.forEach((cp,i)=>{
      if(biggest[cp.l]===i) return;
      const counts = {};
      for(const idx of cp.cells){
        const c=idx%cols, r=(idx/cols)|0;
        for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
          const nc=c+dc, nr=r+dr;
          if(nc<0||nc>=cols||nr<0||nr>=rows) continue;
          const nl = label[nr*cols+nc];
          if(nl>=0 && nl!==cp.l) counts[nl]=(counts[nl]||0)+1;
        }
      }
      const keys = Object.keys(counts);
      if(!keys.length) return;
      const to = Number(keys.reduce((a,b)=> counts[b]>counts[a]?b:a));
      for(const idx of cp.cells) label[idx]=to;
      changed = true;
    });
    if(!changed) return;
  }
}

// How many land cells border `t` per neighboring territory id (4-directional).
function territoryBorderCounts(map, t){
  const counts = {};
  for(const [c,r] of t.cells){
    for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
      const nc=c+dc, nr=r+dr;
      if(!inBounds(map,nc,nr)) continue;
      const o = map.cellTerritory[cellIndex(map,nc,nr)];
      if(o!==-1 && o!==t.id) counts[o]=(counts[o]||0)+1;
    }
  }
  return counts;
}

// Merge every territory that fails territoryFitsBadges into a neighbor — preferring one that
// passes (a superset of a passing territory always passes too, so the result is guaranteed fit
// and nothing cascades), then the longest shared border. An island with no land neighbor at all
// that fails is too small to ever hold its badges, so it's sunk into the sea instead.
function repairUnfitTerritories(map, water){
  const fit = {};
  Object.values(map.territories).forEach(t=>{ fit[t.id] = territoryFitsBadges(map, t.cells); });
  for(let guard=0; guard<2000; guard++){
    const failing = Object.values(map.territories).filter(t=>!fit[t.id]);
    if(!failing.length) return;
    const t = failing.reduce((a,b)=> b.cells.length<a.cells.length ? b : a);
    const border = territoryBorderCounts(map, t);
    const ids = Object.keys(border).map(Number);
    if(!ids.length){
      t.cells.forEach(([c,r])=>{ const idx=cellIndex(map,c,r); map.cellTerritory[idx]=-1; water[idx]=1; });
      delete map.territories[t.id];
      continue;
    }
    ids.sort((a,b)=> (Number(fit[b])-Number(fit[a])) || (border[b]-border[a]));
    const into = map.territories[ids[0]];
    t.cells.forEach(([c,r])=>{ into.cells.push([c,r]); map.cellTerritory[cellIndex(map,c,r)] = into.id; });
    delete map.territories[t.id];
    if(!fit[into.id]) fit[into.id] = territoryFitsBadges(map, into.cells);
  }
}

// Tries to split `t` into 2 compact halves (2-seed relaxed partition inside it, a few different
// random starts). Returns the two cell lists only if BOTH halves still fit 3 badges, else null.
function trySplitTerritory(map, t, weight){
  const {cols, rows} = map;
  const cellIdxs = t.cells.map(([c,r])=> r*cols+c);
  const mask = new Uint8Array(cols*rows);
  cellIdxs.forEach(i=> mask[i]=1);
  for(let attempt=0; attempt<2; attempt++){
    const seeds = farthestPointSeeds(cols, cellIdxs, 2);
    if(seeds.length<2) return null;
    const label = relaxedPartition(cols, rows, mask, cellIdxs, seeds, weight, 4);
    enforceConnectedRegions(cols, rows, cellIdxs, label);
    const halves = [[],[]];
    for(const idx of cellIdxs){ const l=label[idx]; if(l>=0) halves[l].push([idx%cols,(idx/cols)|0]); }
    if(halves[0].length+halves[1].length!==cellIdxs.length || !halves[0].length || !halves[1].length) continue;
    if(territoryFitsBadges(map, halves[0]) && territoryFitsBadges(map, halves[1])) return halves;
  }
  return null;
}

// Restores the territory count after repairUnfitTerritories() merged some away, by splitting the
// largest territories in two for as long as a split keeps both halves fit.
function splitToTargetCount(map, targetCount, weight){
  const unsplittable = new Set();
  // Halves of anything smaller than this can't both fit, so don't bother trying (each failed
  // try costs a couple of full partitions of that territory).
  const minSplittable = 2*idealFitTerritoryCells(map);
  const missing = targetCount - Object.keys(map.territories).length;
  for(let tries=0; tries<2*missing+4; tries++){
    if(Object.keys(map.territories).length>=targetCount) return;
    const cands = Object.values(map.territories).filter(t=>!unsplittable.has(t.id) && t.cells.length>=minSplittable);
    if(!cands.length) return;
    const t = cands.reduce((a,b)=> b.cells.length>a.cells.length ? b : a);
    const halves = trySplitTerritory(map, t, weight);
    if(!halves){ unsplittable.add(t.id); continue; }
    const nt = createTerritory(map);
    t.cells = halves[0];
    nt.cells = halves[1];
    nt.cells.forEach(([c,r])=>{ map.cellTerritory[cellIndex(map,c,r)] = nt.id; });
  }
}

// Area of the smallest regular hexagon that passes territoryFitsBadges' fast path — the ideal
// minimum size of a fit territory.
function idealFitTerritoryCells(map){
  const rC = ARMY_BADGE_RADIUS/map.cellSize;
  const inR = rC + BADGE_FIT_MARGIN_CELLS + 2*rC/Math.sqrt(3);
  return 2*Math.sqrt(3)*inR*inR;
}

// Land cells to budget per territory when capping how many territories a map is asked for. Real
// regions are less regular than the ideal hexagon (coastlines, lakes), so some slack is needed.
// Measured over generated maps, a bigger slack (1.5-1.9x) gives slightly more even sizes but
// noticeably fewer territories on water-heavy maps; 1.35x keeps the most territories, with
// repairUnfitTerritories/splitToTargetCount absorbing the rest.
function minCellsPerFitTerritory(map){
  return Math.ceil(idealFitTerritoryCells(map)*1.35);
}

// Every territory of the result fits 3 army badges, but a very water-heavy roll can leave only
// a handful of islands big enough for that (or none) — so a layout with too few territories to
// play on is re-rolled, easing off the water after the second try, keeping the best one seen.
// generateRandomMap() on a seed of its own: the same seed and arguments always give the same map.
function generateSeededMap(seed, ...args){
  mapRng = seedRng(seed);
  try{ return generateRandomMap(...args); }
  finally{ mapRng = null; }
}
function generateRandomMap(cols, rows, numTerr, numCont, name, waterRatio, waterSpread){
  const ratio = waterRatio===undefined ? 0.28 : waterRatio;
  const playable = Math.min(numTerr, 12);
  // World wrap (left edge joins right edge) — on by default so no corner of the map is a
  // naturally safe pocket to snowball from; config key mapWrapX turns it off.
  const wrapX = !(typeof RUNTIME_CONFIG!=='undefined' && RUNTIME_CONFIG.mapWrapX===false);
  let best = null;
  for(const scale of [1, 1, 0.7, 0.4, 0]){
    const map = generateTerritoryLayout(cols, rows, numTerr, name, ratio*scale, waterSpread, wrapX);
    const count = Object.keys(map.territories).length;
    if(!best || count>Object.keys(best.territories).length) best = map;
    if(count>=playable) break;
  }
  for(let i=0;i<numCont;i++) createContinent(best);
  reassignContinents(best);
  return best;
}

function generateTerritoryLayout(cols, rows, numTerr, name, waterRatio, waterSpread, wrapX){
  const map = newMap(cols, rows, name);
  map.wrapX = !!wrapX;
  const water = generateWaterMask(cols, rows, waterRatio, waterSpread, wrapX);
  // Stray slivers of land pinched off by the coastline are never worth a territory — see
  // submergeTinyLandIslands() above. (Anything bigger that still can't hold its badges is
  // handled per-territory by repairUnfitTerritories below.)
  const avgCellsPerTerritory = (cols*rows)/Math.max(1,numTerr);
  submergeTinyLandIslands(water, cols, rows, Math.max(6, Math.round(avgCellsPerTerritory*0.15)), wrapX);
  map.water = water; // keep for reference/export if needed later

  let landIdxs = [];
  for(let i=0;i<cols*rows;i++) if(!water[i]) landIdxs.push(i);
  if(landIdxs.length===0){
    // degenerate case (100% water requested) - fall back to a small land patch so the map is playable
    for(let r=0;r<Math.max(2,Math.floor(rows/4));r++) for(let c=0;c<cols;c++){ water[r*cols+c]=0; landIdxs.push(r*cols+c); }
  }

  // Never ask the land for more territories than it can hold with every one fitting its badges.
  const targetTerr = Math.max(1, Math.min(numTerr, Math.floor(landIdxs.length/minCellsPerFitTerritory(map))));
  const mask = new Uint8Array(cols*rows);
  landIdxs.forEach(i=> mask[i]=1);
  const weight = makeNoiseWeight(cols, rows, 10, 0.45);
  const label = balancedFitPartition(map, mask, landIdxs, targetTerr, weight);

  const byLabel = {};
  for(const idx of landIdxs){
    const l = label[idx];
    if(l<0) continue;
    (byLabel[l] = byLabel[l] || []).push(idx);
  }
  Object.values(byLabel).forEach(idxs=>{
    const t = createTerritory(map);
    idxs.forEach(idx=>{ map.cellTerritory[idx]=t.id; t.cells.push([idx%cols,(idx/cols)|0]); });
  });
  // Islands no seed reached: each whole island becomes its own territory (repairUnfitTerritories
  // sinks it if it's too small to hold its badges).
  for(const start of landIdxs){
    if(map.cellTerritory[start]!==-1) continue;
    const t = createTerritory(map);
    const q = [start]; map.cellTerritory[start]=t.id;
    for(let qi=0; qi<q.length; qi++){
      const idx=q[qi], c=idx%cols, r=(idx/cols)|0;
      t.cells.push([c,r]);
      for(const [dc,dr] of [[1,0],[-1,0],[0,1],[0,-1]]){
        const nc=c+dc, nr=r+dr;
        if(nc<0||nc>=cols||nr<0||nr>=rows) continue;
        const nidx=nr*cols+nc;
        if(mask[nidx] && map.cellTerritory[nidx]===-1){ map.cellTerritory[nidx]=t.id; q.push(nidx); }
      }
    }
  }

  repairUnfitTerritories(map, water);
  splitToTargetCount(map, targetTerr, weight);

  recomputeGraph(map);
  ensureNoIsolatedTerritories(map);
  return map;
}

// Repeatedly folds any continent left with fewer than minSize territories into whichever
// neighboring continent shares the most border with it (falls back to the smallest other
// continent if it has no land neighbor at all, e.g. a tiny separate island), so no continent
// ends up too small to feel like a meaningful conquest goal. Continents with zero territories
// are left alone — they're simply unused, not a violation of the minimum.
// True if removing `removeId` from continent `contId` would leave its other territories all
// still reachable from each other — used before stealing a border territory in
// enforceMinContinentSize() so a "donor" continent never gets split into 2 disjoint blobs that
// just happen to share a continentId (e.g. removeId was the only link across a narrow isthmus).
function wouldStayConnectedAfterRemoving(map, contId, removeId){
  const members = Object.values(map.territories).filter(t=>t.continentId===contId && t.id!==removeId).map(t=>t.id);
  if(members.length<=1) return true;
  const memberSet = new Set(members);
  const seen = new Set([members[0]]);
  const stack = [members[0]];
  while(stack.length){
    const cur = stack.pop();
    map.territories[cur].neighbors.forEach(nb=>{
      if(memberSet.has(nb) && !seen.has(nb)){ seen.add(nb); stack.push(nb); }
    });
  }
  return seen.size === members.length;
}

// Guarantees every continent ends up with >= minSize territories (never just "tries to, but
// gives up" — measured against real generated maps, the old give-up-when-no-donor-can-spare
// version left a <3-territory continent in ~90% of maps, since with numCont sized the way
// computeMapGenPlan() picks it, there's often barely enough land to go around, let alone slack
// to steal from a neighbor without also pushing IT below the floor). Two moves, in priority
// order:
//  1. Steal one bordering territory at a time from whichever neighboring continent currently has
//     the most to spare, same as before — keeps both continents viable when there's enough slack.
//  2. When no neighbor can spare a territory without itself dropping below the floor, DISSOLVE
//     `target` wholesale into whichever bordering continent it shares the longest border with,
//     rather than leaving it stunted. This is what actually makes the floor a guarantee instead
//     of a best-effort: every dissolve strictly reduces the number of continents left to check
//     (bounded by the starting count), so the loop is guaranteed to terminate with every
//     surviving continent at or above minSize — the trade-off being the map can end up with
//     fewer continents than originally requested when the land doesn't support them all.
function enforceMinContinentSize(map, minSize){
  let guard = 0;
  while(guard++<400){
    const contIds = Object.keys(map.continents).map(Number);
    if(contIds.length<=1) break;
    const sizeOf = {}; contIds.forEach(id=> sizeOf[id]=0);
    Object.values(map.territories).forEach(t=>{ if(t.continentId!=null) sizeOf[t.continentId]++; });
    let target = null;
    contIds.forEach(id=>{
      if(sizeOf[id]>0 && sizeOf[id]<minSize && (target===null || sizeOf[id]<sizeOf[target])) target=id;
    });
    if(target===null) break;

    // Territories in OTHER continents that border `target`, grouped by which continent they
    // belong to — these are the candidates it could grow into, or (if none can spare one) the
    // candidates to dissolve into instead.
    const borderCandidates = {};
    Object.values(map.territories).forEach(t=>{
      if(t.continentId===target) return;
      if([...t.neighbors].some(nb=> map.territories[nb].continentId===target)){
        (borderCandidates[t.continentId] = borderCandidates[t.continentId]||[]).push(t.id);
      }
    });
    const donors = Object.keys(borderCandidates).map(Number);
    if(donors.length===0) break; // no land neighbor at all (a fully separate island) — nothing adjacent to grow into or dissolve into

    donors.sort((a,b)=> sizeOf[b]-sizeOf[a]);
    const donor = donors.find(id=> sizeOf[id]-1 >= minSize
      && borderCandidates[id].some(tid=> wouldStayConnectedAfterRemoving(map, id, tid)));
    if(donor!==undefined){
      const validPicks = borderCandidates[donor].filter(tid=> wouldStayConnectedAfterRemoving(map, donor, tid));
      const pick = randChoice(validPicks);
      map.territories[pick].continentId = target;
      continue;
    }
    // Fallback: dissolve `target` into whichever neighbor it borders the most (most border
    // territories = most natural fit), merging its land in wholesale.
    let bestMergeCont = donors[0], bestMergeCount = -1;
    donors.forEach(id=>{
      if(borderCandidates[id].length>bestMergeCount){ bestMergeCount=borderCandidates[id].length; bestMergeCont=id; }
    });
    Object.values(map.territories).forEach(t=>{ if(t.continentId===target) t.continentId = bestMergeCont; });
    delete map.continents[target];
  }
}

// Picks k seed territories out of ids, spread as far apart from each other as possible
// (greedy farthest-point sampling over territory centroids). Purely random seeds occasionally
// land two continent seeds close together, or leave one stuck in a corner/peninsula with few
// neighbors to grow into — its round-robin growth then stalls early and it ends up too small,
// tripping enforceMinContinentSize() and collapsing into its neighbor. Starting seeds spread
// out gives each one roughly equal room to grow into before meeting a rival.
function pickSpreadSeeds(map, ids, k){
  const pool = shuffle(ids.slice());
  const chosen = [pool.pop()];
  while(chosen.length<k && pool.length){
    let bestIdx=0, bestDist=-1;
    for(let i=0;i<pool.length;i++){
      const c = map.territories[pool[i]].centroid;
      let minD = Infinity;
      for(const cid of chosen){
        const cc = map.territories[cid].centroid;
        const d = (c.x-cc.x)**2 + (c.y-cc.y)**2;
        if(d<minD) minD = d;
      }
      if(minD>bestDist){ bestDist=minD; bestIdx=i; }
    }
    chosen.push(pool.splice(bestIdx,1)[0]);
  }
  return chosen;
}

// Reassigns every territory's continentId across the map's EXISTING continents — never
// creates or deletes a continent. Used both right after generateRandomMap() seeds fresh
// continents above, and standalone by the editor's "Tự động chia lại" button to redo this
// on a map you've already been hand-editing (e.g. after adding a continent by hand, which
// otherwise starts out with zero territories — see createContinent()).
//
// Prefers continent borders that follow coastlines (water) rather than cutting through
// contiguous land: each connected landmass (component of the territory graph — water always
// breaks graph edges) is treated as a unit. Small landmasses are kept whole and merged
// wholesale into a continent; only the largest landmasses get split internally when there
// are more continents than landmasses.
function reassignContinents(map){
  const contIds = Object.keys(map.continents).map(Number);
  const numCont = contIds.length;
  if(numCont===0) return;

  const components = findConnectedComponents(map).map(ids=>({
    ids, size: ids.reduce((s,id)=> s+map.territories[id].cells.length, 0)
  }));
  components.sort((a,b)=> b.size-a.size);

  // How many continents does each landmass get? Proportional apportionment (the "largest
  // remainder" method used for seat allocation) rather than "1 baseline each + leftovers to
  // whoever's biggest" — the baseline approach let two very differently-sized landmasses both
  // end up as exactly 1 whole continent each whenever there happened to be enough continents
  // to go around 1-for-1, with no mechanism left to correct the size gap between them.
  let contsPerComponent;
  if(components.length <= numCont){
    const totalLand = components.reduce((s,c)=>s+c.size,0);
    const quotas = components.map(c=> c.size/totalLand*numCont);
    contsPerComponent = quotas.map(q=> Math.floor(q));
    let remaining = numCont - contsPerComponent.reduce((a,b)=>a+b,0);
    // remaining continents (from the fractional part of each quota) go to the landmasses
    // with the largest leftover remainder first — standard largest-remainder apportionment.
    const order = components.map((_,i)=>i).sort((a,b)=> (quotas[b]-contsPerComponent[b]) - (quotas[a]-contsPerComponent[a]));
    for(let k=0;k<remaining;k++) contsPerComponent[order[k]]++;
    // a landmass whose quota rounds down to 0 continents just falls through to the
    // leftover-merge step below instead of getting a whole (tiny) continent to itself.
  } else {
    // fewer continents than landmasses: keep the `numCont` largest landmasses as their own
    // continent, and merge every smaller landmass wholesale into one of those later.
    contsPerComponent = components.map((c,i)=> i<numCont ? 1 : 0);
  }

  const pool = shuffle(contIds.slice()); // drained at most `numCont` times total below
  const contOwnedByComponent = components.map(()=>false);
  components.forEach((comp, ci)=>{
    // A landmass can have fewer territories than its area-proportional quota of continents
    // (few, large territories) — never ask it to seed more continents than it has territories.
    const wantConts = Math.min(contsPerComponent[ci], comp.ids.length);
    if(wantConts<=0) return;
    contOwnedByComponent[ci] = true;
    const myContIds = pool.splice(0, wantConts);
    const seedIds = pickSpreadSeeds(map, comp.ids, myContIds.length);
    const assigned = {};
    // Round-robin growth (one claim per continent per pass, not a full-frontier flood) so
    // continents in the same landmass grow at an even rate — otherwise a seed that happens
    // to have more open neighbors nearby snowballs into a much bigger share of the landmass.
    const frontiers = myContIds.map((cont,i)=>{ assigned[seedIds[i]]=cont; return [seedIds[i]]; });
    let anyMoved = true;
    while(anyMoved){
      anyMoved = false;
      for(let fi=0; fi<frontiers.length; fi++){
        const q = frontiers[fi], cont = myContIds[fi];
        while(q.length){
          const tid = q.shift();
          const nbs = shuffle([...map.territories[tid].neighbors]).filter(nb=>assigned[nb]===undefined);
          if(nbs.length===0) continue; // exhausted, try the next queued tile instead
          assigned[nbs[0]] = cont;
          q.push(tid); // may still have more unclaimed neighbors later
          q.push(nbs[0]);
          anyMoved = true;
          break; // one claim per continent this pass, then move on to the next continent
        }
      }
    }
    comp.ids.forEach(tid=>{ map.territories[tid].continentId = assigned[tid] ?? myContIds[0]; });
  });

  // merge leftover landmasses (too small to warrant their own continent) wholesale into
  // whichever continent is CURRENTLY smallest — never split one (so this never introduces a
  // land border mid-component), while keeping overall continent sizes from drifting too far
  // apart from each other.
  const sizeOf = {}; contIds.forEach(id=> sizeOf[id]=0);
  Object.values(map.territories).forEach(t=>{ if(t.continentId!=null) sizeOf[t.continentId]++; });
  components.forEach((comp, ci)=>{
    if(contOwnedByComponent[ci]) return;
    let targetCont = contIds[0];
    contIds.forEach(id=>{ if(sizeOf[id]<sizeOf[targetCont]) targetCont=id; });
    comp.ids.forEach(tid=> map.territories[tid].continentId = targetCont);
    sizeOf[targetCont] += comp.ids.length;
  });
  // Continents the clamp above left with no territory at all would be invisible and broken
  // (enforceMinContinentSize only grows continents that already have >=1 territory).
  contIds.forEach(id=>{ if(sizeOf[id]<=0) delete map.continents[id]; });

  enforceMinContinentSize(map, 3);
  assignContinentColors(map);

  // bonuses based on continent size
  Object.values(map.continents).forEach(cont=>{
    const size = Object.values(map.territories).filter(t=>t.continentId===cont.id).length;
    cont.bonus = Math.max(2, Math.round(size/2)+1);
  });
}

// Colors continents (continent view / editor's "Xem châu lục" fill) so that any 2 continents
// sharing a land border always get visually distinct colors, instead of colors falling out of
// createContinent()'s arbitrary id-order assignment — which has no idea which continents will
// end up adjacent, so 2 similar palette shades (e.g. 2 different greens) could easily land next
// to each other with no visible seam between them. Greedy graph coloring: process continents
// most-constrained (most neighbors) first, and for each pick whichever palette color is
// unused by its already-colored neighbors and farthest (in RGB distance) from the ones that
// are used, so even a palette color forced to repeat lands as far away as possible.
function assignContinentColors(map){
  const adjacency = {};
  Object.values(map.territories).forEach(t=>{
    if(t.continentId==null) return;
    [...t.neighbors].forEach(nb=>{
      const nc = map.territories[nb].continentId;
      if(nc!=null && nc!==t.continentId){
        (adjacency[t.continentId] = adjacency[t.continentId] || new Set()).add(nc);
      }
    });
  });
  const contIds = Object.keys(map.continents).map(Number);
  const order = contIds.slice().sort((a,b)=> (adjacency[b]?adjacency[b].size:0) - (adjacency[a]?adjacency[a].size:0));
  const assigned = {};
  order.forEach(cid=>{
    const neighborColors = [...(adjacency[cid]||[])].map(nid=>assigned[nid]).filter(Boolean);
    let best=null, bestScore=-Infinity;
    PALETTE_CONT.forEach(color=>{
      if(neighborColors.includes(color)) return; // exact reuse only allowed if truly unavoidable
      const score = neighborColors.length ? Math.min(...neighborColors.map(nc=>colorDistance(nc,color))) : Infinity;
      if(score>bestScore){ bestScore=score; best=color; }
    });
    if(best===null){
      PALETTE_CONT.forEach(color=>{
        const score = neighborColors.length ? Math.min(...neighborColors.map(nc=>colorDistance(nc,color))) : Infinity;
        if(score>bestScore){ bestScore=score; best=color; }
      });
    }
    assigned[cid] = best;
    map.continents[cid].color = best;
  });
}

/* ---- src/js/04-game-state.js ---- */
/* =========================================================================
   GAME STATE
   ========================================================================= */
let game = null; // set on start
let showContinentsGame = false;
// Combat-log filter (toggled by btnToggleLogFilter, see 08-wiring.js): when true,
// renderCombatLog() only shows entries tagged with player 0's id — "your" slot, same
// convention as isHuman:i===0 in readPlayerConfigs() (still true even in spectator mode,
// where index 0 is AI-controlled but is still nominally "your" side).
let logFilterMine = false;

function standardStartingArmies(numPlayers){
  const table = {2:40,3:35,4:30,5:25,6:20};
  return table[numPlayers] || 20;
}

const CARD_TYPES = ['infantry','cavalry','artillery'];
const CARD_ICON = {infantry:'🪖', cavalry:'🐎', artillery:'💣'};

// Three trade-bonus rules a game can be started with (see game.tradeRule, chosen in setup):
//  - fixed:       classic escalating table, but it PLATEAUS at the last table value forever
//                 once reached — no reason to ever hold cards, every trade from then on pays
//                 exactly the same.
// The table (tradeValues), the progressive step and the exponential base/growth are from the config.
//  - progressive: the table keeps climbing forever (+5 per trade) based on a count SHARED by
//                 all players — trading later (after opponents have also traded) pays more, so
//                 holding cards is a real (if risky) strategy. This is the game's original/
//                 default behavior.
//  - exponential: value compounds ~1.3x per trade, but tracked PER PLAYER instead of globally —
//                 an opponent trading a lot doesn't help or hurt you; only your OWN trade count
//                 matters, so the earlier and more often YOU personally trade, the faster your
//                 own trades ramp up.
function tradeInValue(rule, tradeCount, personalTradeCount){
  const C = RUNTIME_CONFIG, table = C.tradeValues;
  if(rule==='exponential') return Math.round(C.tradeExpBase*Math.pow(C.tradeExpGrowth, personalTradeCount));
  if(rule==='fixed') return table[Math.min(tradeCount, table.length-1)];
  // progressive (default)
  if(tradeCount < table.length) return table[tradeCount];
  return table[table.length-1] + (tradeCount-table.length+1)*C.tradeProgressiveStep;
}

// playerConfigs: [{name, color, personality, isHuman}, ...] — index 0 is "you" (a real human
// unless spectator mode made them AI-controlled too), built by readPlayerConfigs() in the
// setup screen.
// seed: optional — everything random in the game follows from it (see random() in
// 00-core-utils.js); left out, a fresh one is picked.
function initGame(playerConfigs, difficulty, spectator, allianceEnabled, tradeRule, seed){
  if(seed==null) seed = newRandomSeed();
  game = { rng: seedRng(seed) }; // live from here on, so the shuffles below already use it
  spectatorMode = !!spectator;
  aiPaused = false; pendingAIResume = null;
  host.onGameInit(); // the browser resets zoom and leftover fades/tweens from the last game
  const startArmies = standardStartingArmies(playerConfigs.length);
  // totalReinforced/totalKills are cumulative since game start (shown in the topbar), unlike
  // the per-turn capturedThisTurn/killedThisTurn flags which reset every endTurn().
  const players = playerConfigs.map((cfg,id)=>({
    id, name:cfg.name, isHuman:cfg.isHuman, color:cfg.color, alive:true, cards:[],
    capturedThisTurn:false, killedThisTurn:false, totalReinforced:startArmies, totalKills:0,
    personality: cfg.isHuman ? 'balanced' : cfg.personality, eliminatedRound:null,
    personalTradeCount: 0, // only used by the 'exponential' trade rule (see tradeInValue())
  }));
  const terrIds = shuffle(Object.keys(mapData.territories).map(Number));
  const owner = {}; const armies = {};
  terrIds.forEach((id,i)=>{ owner[id] = i % players.length; armies[id] = 1; });

  const pool = {};
  players.forEach(p=> pool[p.id] = startArmies - terrIds.filter(id=>owner[id]===p.id).length);

  game = {
    seed, rng: game.rng,
    players, owner, armies, pool,
    turnOrder: shuffle(players.map(p=>p.id)),
    turnIdx: 0,
    phase: 'setup-place', // setup-place -> reinforce -> attack -> fortify
    difficulty,
    roundNumber: 1, // +1 each time turnIdx wraps back to the start of turnOrder (see endTurn())
    reinforceRemaining: 0,
    tradeRule: tradeRule || 'progressive',
    tradeCount: 0,
    selectedFrom: null, selectedTo: null,
    log: [],
    over: false,
    allianceEnabled: !!allianceEnabled,
    biggestBattle: null, // set by recordBattleStat(), shown on the end-game summary screen
  };
  logMsg('info', 'Ván chơi bắt đầu! '+players.length+' người chơi trên bản đồ "'+mapData.name+'".');
}

function currentPlayerId(){ return game.turnOrder[game.turnIdx]; }
function currentPlayer(){ return game.players[currentPlayerId()]; }
function ownedTerritories(pid){ return Object.keys(game.owner).map(Number).filter(id=>game.owner[id]===pid); }
function isAlive(pid){ return game.players[pid].alive; }

// playerIds: which player(s) this entry is "about" — a single id, an array of ids, or
// omitted for a global/system message (game start, etc). Read by renderCombatLog() when
// logFilterMine is on: an entry with no playerIds always shows, one with playerIds only
// shows if player 0 ("you", see logFilterMine above) is among them.
function logMsg(type,msg,playerIds){
  const ids = playerIds==null ? null : (Array.isArray(playerIds) ? playerIds : [playerIds]);
  game.log.push({type,msg,playerIds:ids});
  host.renderCombatLog();
}

/* ---------------- Setup placement (initial armies) ---------------- */
function allPoolsEmpty(){ return game.players.every(p=> !p.alive || game.pool[p.id]<=0); }

function setupPlaceNext(){
  // if human has pool left, wait for click; else auto-place for AI/human w/ 0
  if(allPoolsEmpty()){
    beginReinforcePhase();
    return;
  }
  const p = currentPlayer();
  if(game.pool[p.id] <= 0){
    advanceSetupTurn();
    return;
  }
  if(!p.isHuman){
    // AI auto place 1 army on a border territory (or random).
    // Kept fast (no spectator delay) even in "watch AI" mode — placing armies one at a
    // time isn't interesting to watch slowly, so this phase always runs at full speed;
    // the 1s pacing kicks in starting from the reinforce/attack/fortify phases instead.
    aiSchedule(()=>{
      if(!game || game.over) return;
      const mine = ownedTerritories(p.id);
      const target = pickAIReinforceTarget(p.id, mine);
      game.armies[target]++;
      game.pool[p.id]--;
      host.renderGame();
      advanceSetupTurn();
    }, 120);
  } else {
    host.renderGame();
    host.setActionHint('Nhấp vào lãnh thổ của bạn để đặt quân. Còn lại: '+game.pool[p.id]);
  }
}
function advanceSetupTurn(){
  game.turnIdx = (game.turnIdx+1) % game.turnOrder.length;
  setupPlaceNext();
}

// Places 1 army for the human into `terrId` if it's currently their turn/valid, same effect as
// a single click during setup-place. Returns whether a placement actually happened.
function attemptSetupPlacement(terrId){
  if(!game || game.over || game.phase!=='setup-place') return false;
  const p = currentPlayer();
  if(!p.isHuman || terrId===-1 || game.owner[terrId]!==p.id || game.pool[p.id]<=0) return false;
  game.armies[terrId]++; game.pool[p.id]--;
  host.renderGame();
  if(allPoolsEmpty()){ beginReinforcePhase(); }
  else { host.setActionHint('Còn lại: '+game.pool[p.id]+' quân để đặt.'); advanceSetupTurn(); }
  return true;
}

// Whether a press-and-hold placement loop should keep waiting for another turn to come back
// around (turn order cycles through the AI between each of the human's own placements, so
// most ticks while holding land mid-AI-turn — that's not a reason to stop), vs give up
// entirely because the phase ended or this spot/player can no longer place here.
function canKeepHoldingSetupPlacement(terrId){
  if(!game || game.over || game.phase!=='setup-place') return false;
  const p = currentPlayer();
  if(p.isHuman && (game.owner[terrId]!==p.id || game.pool[p.id]<=0)) return false;
  return true;
}

// Alternative to the turn-based setupPlaceNext() flow: dump every player's starting
// pool onto their own territories at random, all at once, then go straight to
// reinforce. Used when the "Đặt quân thủ công lúc bắt đầu" setting is off.
function autoPlaceInitialArmies(){
  game.players.forEach(p=>{
    const mine = ownedTerritories(p.id);
    while(game.pool[p.id]>0){
      game.armies[randChoice(mine)]++;
      game.pool[p.id]--;
    }
  });
}

function beginReinforcePhase(){
  game.turnIdx = 0;
  game.phase = 'reinforce';
  // Captured here (not at initGame time) since this is the point where territory/army
  // placement is actually finalized — reached the same way whether that came from the
  // auto-place fast path or a full manual setup-place sequence. Read back by
  // replaySameGame() so "Chơi lại" on the game-over screen can restart from this exact
  // starting position (same map/players/territories/armies) instead of a fresh shuffle.
  game.startSnapshot = {
    players: game.players.map(p=>({name:p.name, isHuman:p.isHuman, color:p.color, personality:p.personality})),
    owner: {...game.owner},
    armies: {...game.armies},
    turnOrder: [...game.turnOrder],
    difficulty: game.difficulty,
    allianceEnabled: game.allianceEnabled,
    tradeRule: game.tradeRule,
    spectatorMode: spectatorMode,
  };
  startReinforce();
}

/* ---------------- Reinforcement ---------------- */
// Same math computeReinforcements() used to do inline, just broken out into its parts (base
// from territory count + which continents kicked in a bonus) so the reinforce-phase log line
// can show WHERE the number came from instead of just the final total.
function reinforcementBreakdown(pid){
  const mine = ownedTerritories(pid);
  const base = Math.max(RUNTIME_CONFIG.reinforceMin, Math.floor(mine.length/RUNTIME_CONFIG.reinforceDivisor));
  const continentBonuses = [];
  Object.values(mapData.continents).forEach(cont=>{
    const contTerrs = Object.values(mapData.territories).filter(t=>t.continentId===cont.id).map(t=>t.id);
    if(contTerrs.length>0 && contTerrs.every(id=>game.owner[id]===pid)) continentBonuses.push({name:cont.name, bonus:cont.bonus});
  });
  const total = base + continentBonuses.reduce((s,c)=>s+c.bonus, 0);
  return {total, base, territoryCount:mine.length, continentBonuses};
}
function computeReinforcements(pid){ return reinforcementBreakdown(pid).total; }

function startReinforce(){
  const p = currentPlayer();
  host.showTurnIntro(p);
  game.phase='reinforce';
  const breakdown = reinforcementBreakdown(p.id);
  game.reinforceRemaining = breakdown.total;
  p.totalReinforced += game.reinforceRemaining;
  const parts = [`${breakdown.territoryCount} lãnh thổ → ${breakdown.base}`]
    .concat(breakdown.continentBonuses.map(c=>`${c.name} +${c.bonus}`));
  logMsg('info', `${p.name} nhận ${game.reinforceRemaining} quân tăng viện (${parts.join(', ')}).`, p.id);
  // Render right away regardless of whose turn this is — otherwise the previous (human) turn's
  // phase-end button/phase badge would stay on screen, still clickable, for the whole
  // TURN_INTRO_TOTAL_MS delay below before the AI actually starts acting.
  host.renderGame();
  if(!p.isHuman){
    // Held off by the turn-intro banner's own lifetime (see TURN_INTRO_TOTAL_MS) so the AI
    // doesn't start acting while the "lượt của X" banner is still showing/fading for the
    // previous turn's viewer. Goes through aiSchedule (not a raw setTimeout) so pausing the AI
    // mid-banner still works.
    aiSchedule(()=> aiRunFullTurn(p.id), TURN_INTRO_TOTAL_MS);
  } else {
    // forced trade if 5+ cards
    if(p.cards.length>=5){ host.openCardsModal(true); }
    host.setActionHint('Nhấp vào lãnh thổ của bạn để đặt quân. Còn lại: '+game.reinforceRemaining);
  }
}

function placeReinforcement(terrId){
  const p = currentPlayer();
  if(game.owner[terrId]!==p.id) return false;
  if(game.reinforceRemaining<=0) return false;
  game.armies[terrId]++;
  game.reinforceRemaining--;
  host.renderGame();
  // Auto-advances once every troop is placed — unlike attack/fortify, there's no real decision
  // left to make in reinforce once the pool hits 0, so a manual "kết thúc" click here would just
  // be a needless extra tap. (If the player has 5+ cards, the forced-trade modal blocks placing
  // the LAST troops until they trade down — see startReinforce()/endAttackPhase() — so this only
  // ever fires once that's already resolved.)
  if(game.reinforceRemaining<=0){
    beginAttackPhase();
  } else {
    host.setActionHint('Còn lại: '+game.reinforceRemaining+' quân để đặt.');
  }
  return true;
}

/* ---------------- Attack ---------------- */
function beginAttackPhase(){
  game.phase='attack';
  game.selectedFrom=null; game.selectedTo=null;
  // Counts entries into this phase (including the forced-card-trade bounce back into it), so
  // the browser can tell a fresh entry apart and restart its "Kết thúc tấn công" delay — see
  // renderPhaseActions() in 06-render-game.js.
  game.attackPhaseEntries = (game.attackPhaseEntries||0)+1;
  host.renderGame();
  host.setActionHint('Chọn lãnh thổ của bạn (≥2 quân) rồi lãnh thổ địch liền kề để tấn công.');
}

function canAttack(fromId,toId,pid){
  if(game.owner[fromId]!==pid) return false;
  if(game.owner[toId]===pid) return false;
  if(game.armies[fromId]<2) return false;
  return mapData.territories[fromId].neighbors.has(toId);
}

function doBattle(fromId,toId,opts){
  // silent: skip dice display/log/render for this single round — used by the AI's
  // battleBatch() to fight many rounds back-to-back without a render per round, then
  // the caller shows the dice/log/render once for the whole batch (see 05-ai.js).
  const silent = !!(opts && opts.silent);
  const attArmies = game.armies[fromId];
  const defArmies = game.armies[toId];
  const attDice = clamp(attArmies-1,1,3);
  const defDice = clamp(defArmies,1,2);
  const ad = Array.from({length:attDice},rollDie).sort((a,b)=>b-a);
  const dd = Array.from({length:defDice},rollDie).sort((a,b)=>b-a);
  let attLoss=0, defLoss=0;
  const pairs = Math.min(ad.length,dd.length);
  const results=[];
  for(let i=0;i<pairs;i++){
    if(ad[i]>dd[i]){ defLoss++; results.push({a:ad[i],d:dd[i],win:true}); }
    else { attLoss++; results.push({a:ad[i],d:dd[i],win:false}); }
  }
  game.armies[fromId]-=attLoss;
  game.armies[toId]-=defLoss;
  if(!silent) host.showDice(ad,dd,results);
  const attP = game.players[game.owner[fromId]];
  const defP = game.players[game.owner[toId]];
  if(defLoss>0) attP.killedThisTurn = true; // feeds the 'on_kill' cardAwardEvent mode
  attP.totalKills += defLoss; // cumulative since game start, shown in the topbar
  if(!silent) logMsg('attack', `${attP.name} tấn công ${mapData.territories[toId].name} từ ${mapData.territories[fromId].name}: mất ${attLoss}, đối phương mất ${defLoss}.`, [attP.id, defP.id]);
  let captured=false, moving=null, maxMovable=null;
  if(game.armies[toId]<=0){
    captured=true;
    // Risk rule: must move at least as many armies as dice used in the winning roll. Apply
    // that guaranteed minimum immediately so game state is always valid; the caller (human
    // attack entry points in 06-render-game.js) decides whether to offer a modal to move
    // more — doBattle() itself doesn't, since it's also called silently by the AI/all-out
    // batch loop where no modal should ever appear mid-batch.
    const conquerMin = attDice;
    maxMovable = game.armies[fromId]-1;
    moving = Math.max(1, Math.min(conquerMin, maxMovable));
    const oldOwner = game.owner[toId];
    game.owner[toId] = game.owner[fromId];
    game.armies[toId] = moving;
    game.armies[fromId] -= moving;
    attP.capturedThisTurn = true;
    if(!silent) logMsg('capture', `${attP.name} chiếm được ${mapData.territories[toId].name}!`, [attP.id, oldOwner]);
    checkElimination(oldOwner, attP.id);
  }
  if(!silent) host.renderGame();
  return {attLoss,defLoss,captured,ad,dd,results,moving,maxMovable};
}

// Tracks the single attack (1 human click, or 1 AI battleBatch) with the highest combined
// army loss across the whole game, shown on the end-game summary screen (showGameOver()).
function recordBattleStat(attackerName, defenderName, fromName, toName, totalLoss){
  if(totalLoss<=0) return;
  if(!game.biggestBattle || totalLoss > game.biggestBattle.totalLoss){
    game.biggestBattle = {attackerName, defenderName, fromName, toName, totalLoss, round: game.roundNumber};
  }
}

function checkElimination(pid, byPid){
  if(pid===undefined) return;
  const p = game.players[pid];
  if(!p.alive) return;
  if(ownedTerritories(pid).length===0){
    p.alive=false;
    p.eliminatedRound = game.roundNumber;
    logMsg('capture', `${p.name} đã bị loại khỏi ván chơi!`, byPid==null ? pid : [pid, byPid]);
    // transfer cards
    const byP = game.players[byPid];
    if(byP && p.cards.length){ byP.cards = byP.cards.concat(p.cards); p.cards=[]; }
    checkWinCondition();
  }
}

function checkWinCondition(){
  const alivePlayers = game.players.filter(p=>p.alive);
  if(alivePlayers.length<=1){
    game.over=true;
    host.showGameOver(alivePlayers[0]);
  }
}

/* ---------------- Fortify ---------------- */
function beginFortifyPhase(){
  game.phase='fortify';
  game.selectedFrom=null; game.selectedTo=null;
  host.renderGame();
  if(!currentPlayer().isHuman) return; // handled by AI routine
  host.setActionHint('Chọn lãnh thổ nguồn rồi đích để chuyển quân, hoặc kết thúc lượt.');
}

function pathExistsOwned(fromId,toId,pid){
  const seen=new Set([fromId]); const stack=[fromId];
  while(stack.length){
    const cur=stack.pop();
    if(cur===toId) return true;
    mapData.territories[cur].neighbors.forEach(n=>{
      if(!seen.has(n) && game.owner[n]===pid){ seen.add(n); stack.push(n); }
    });
  }
  return false;
}

function endTurn(){
  const p = currentPlayer();
  host.beforeEndTurn(p);
  // cardAwardEvent config (Settings screen) picks which of the 3 rules grants a card
  // at the end of this player's turn. Shared by human and AI turns alike, since both
  // go through this same function.
  const mode = RUNTIME_CONFIG.cardAwardEvent;
  const awardCard = mode==='on_turn_end' ? true
    : mode==='on_kill' ? p.killedThisTurn
    : p.capturedThisTurn; // 'on_capture' (default)
  if(awardCard){
    const type = CARD_TYPES[rand(3)];
    p.cards.push(type);
    logMsg('info', p.name+' nhận được 1 thẻ bài '+CARD_ICON[type]+'.', p.id);
  }
  p.capturedThisTurn=false;
  p.killedThisTurn=false;
  do {
    game.turnIdx = (game.turnIdx+1) % game.turnOrder.length;
    if(game.turnIdx===0) game.roundNumber++; // wrapped back to the start of turnOrder = a new round
  } while(!isAlive(currentPlayerId()));
  if(game.over) return;
  startReinforce();
}

/* ---- src/js/04b-actions.js ---- */
/* =========================================================================
   PLAYER ACTIONS (core)
   ---------------------------------------------------------------------
   The one way a human player changes a game: applyAction(pid, action). It
   checks the move against the rules — whose turn, which phase, who owns what,
   how many armies — and only then carries it out with the functions in
   04-game-state.js. The browser calls it for every click (dispatch() in
   07b-game-ui.js); the server calls it for every request, so nothing a client
   sends is trusted beyond "this player asks to do this".

   Actions:
     {type:'place', terrId}                 one army: initial placement or reinforcement
     {type:'trade', cards:[i,j,k]}          trade in three cards (positions in the hand)
     {type:'attack', from, to, allOut}      one dice round, or keep rolling until it ends
     {type:'moveAfterCapture', count}       extra armies into the territory just captured
     {type:'endAttack'}
     {type:'fortify', from, to, count}
     {type:'endTurn'}

   Returns {ok:true, result} or {ok:false, error:<code>}.
   ========================================================================= */

// A hand this big has to be traded down before doing anything else.
const FORCED_TRADE_HAND = 5;

function isTerritoryId(id){ return Number.isInteger(id) && !!mapData.territories[id]; }

// Back to the reinforce phase with nothing to place, so the only way forward is trading cards
// (which hands out armies to place, which leads back into the attack phase).
function bounceToForcedTrade(){
  game.phase = 'reinforce';
  game.reinforceRemaining = 0;
  game.pendingCapture = null;
}

// One human attack: a single dice round, or (allOut) round after round until the target falls
// or the source can't attack any more. Assumes the attack is legal.
function performAttack(p, fromId, toId, allOut){
  const fromName = mapData.territories[fromId].name, toName = mapData.territories[toId].name;
  const defenderId = game.owner[toId];
  const defenderName = game.players[defenderId].name;
  const fromCountBefore = game.armies[fromId], toCountBefore = game.armies[toId];
  let rounds = 0, attLoss = 0, defLoss = 0, captured = false, lastRes = null;
  if(allOut){
    // silent rounds, then one summary — same as the AI's battleBatch() in 05-ai.js
    while(game.armies[fromId]>=2 && canAttack(fromId, toId, p.id)){
      lastRes = doBattle(fromId, toId, {silent:true});
      rounds++; attLoss += lastRes.attLoss; defLoss += lastRes.defLoss;
      if(lastRes.captured){ captured = true; break; }
    }
    const roundsLabel = rounds>1 ? ` (${rounds} hiệp)` : '';
    logMsg('attack', `${p.name} tấn công ${toName} từ ${fromName}${roundsLabel}: mất ${attLoss}, đối phương mất ${defLoss}.`, [p.id, defenderId]);
    host.showDice(lastRes.ad, lastRes.dd, lastRes.results);
    if(captured) logMsg('capture', `${p.name} chiếm được ${toName}!`, [p.id, defenderId]);
  } else {
    lastRes = doBattle(fromId, toId);
    rounds = 1; attLoss = lastRes.attLoss; defLoss = lastRes.defLoss; captured = lastRes.captured;
  }
  recordBattleStat(p.name, defenderName, fromName, toName, attLoss+defLoss);
  // Captured with armies to spare: the player may send more in (moveAfterCapture) until their
  // next action. The rule's minimum has already moved (see doBattle()).
  const extraMax = captured && !game.over ? lastRes.maxMovable-lastRes.moving : 0;
  game.pendingCapture = extraMax>0 ? {from:fromId, to:toId} : null;
  // Eliminating someone hands over their cards — a hand of 5+ has to be traded down right away.
  const mustTrade = !game.over && p.cards.length>=FORCED_TRADE_HAND;
  if(mustTrade) bounceToForcedTrade();
  return {
    fromId, toId, defenderId, rounds, attLoss, defLoss, captured,
    fromCountBefore, toCountBefore, fromCountAfter: game.armies[fromId], toCountAfter: game.armies[toId],
    moved: captured ? lastRes.moving : 0, extraMax: mustTrade ? 0 : extraMax, mustTrade, over: game.over,
  };
}

function applyAction(pid, action){
  const res = runAction(pid, action);
  // The chance to send more armies into a captured territory lapses with the next move made
  // (a refused action changes nothing at all, this included).
  if(res.ok && action.type!=='attack' && action.type!=='moveAfterCapture' && game.pendingCapture) game.pendingCapture = null;
  return res;
}
function runAction(pid, action){
  const fail = error=> ({ok:false, error});
  if(!game || game.over) return fail('game_over');
  if(!action || typeof action.type!=='string') return fail('bad_action');
  if(currentPlayerId()!==pid) return fail('not_your_turn');
  const p = game.players[pid];
  if(!p || !p.isHuman || !p.alive) return fail('not_your_turn');

  switch(action.type){
    case 'place': {
      const terrId = action.terrId;
      if(!isTerritoryId(terrId) || game.owner[terrId]!==pid) return fail('not_your_territory');
      if(game.phase==='setup-place'){
        if(game.pool[pid]<=0) return fail('nothing_to_place');
        attemptSetupPlacement(terrId);
        return {ok:true, result:{}};
      }
      if(game.phase!=='reinforce') return fail('wrong_phase');
      if(p.cards.length>=FORCED_TRADE_HAND) return fail('must_trade_first');
      if(game.reinforceRemaining<=0) return fail('nothing_to_place');
      placeReinforcement(terrId);
      return {ok:true, result:{}};
    }
    case 'trade': {
      if(game.phase!=='reinforce') return fail('wrong_phase');
      const idx = action.cards;
      if(!Array.isArray(idx) || idx.length!==3 || new Set(idx).size!==3 ||
         !idx.every(i=> Number.isInteger(i) && i>=0 && i<p.cards.length)) return fail('bad_cards');
      const kinds = new Set(idx.map(i=>p.cards[i])).size;
      if(kinds!==1 && kinds!==3) return fail('bad_cards');
      const before = game.reinforceRemaining;
      tradeCards(p, idx);
      return {ok:true, result:{armies: game.reinforceRemaining-before, mustTrade: p.cards.length>=FORCED_TRADE_HAND}};
    }
    case 'attack': {
      if(game.phase!=='attack') return fail('wrong_phase');
      const {from, to} = action;
      if(!isTerritoryId(from) || !isTerritoryId(to) || !canAttack(from, to, pid)) return fail('illegal_attack');
      return {ok:true, result: performAttack(p, from, to, !!action.allOut)};
    }
    case 'moveAfterCapture': {
      const pc = game.pendingCapture;
      if(game.phase!=='attack' || !pc) return fail('nothing_to_move');
      const count = action.count;
      if(!Number.isInteger(count) || count<0 || count>game.armies[pc.from]-1) return fail('bad_count');
      game.armies[pc.from] -= count; game.armies[pc.to] += count;
      game.pendingCapture = null;
      host.renderGame();
      return {ok:true, result:{from:pc.from, to:pc.to, count}};
    }
    case 'endAttack': {
      if(game.phase!=='attack') return fail('wrong_phase');
      if(p.cards.length>=FORCED_TRADE_HAND){
        bounceToForcedTrade();
        host.renderGame();
        return {ok:true, result:{mustTrade:true}};
      }
      beginFortifyPhase();
      return {ok:true, result:{mustTrade:false}};
    }
    case 'fortify': {
      if(game.phase!=='fortify') return fail('wrong_phase');
      const {from, to, count} = action;
      if(!isTerritoryId(from) || !isTerritoryId(to) || from===to ||
         game.owner[from]!==pid || game.owner[to]!==pid || !pathExistsOwned(from, to, pid)) return fail('illegal_fortify');
      if(!Number.isInteger(count) || count<1 || count>game.armies[from]-1) return fail('bad_count');
      game.armies[from] -= count; game.armies[to] += count;
      logMsg('info', p.name+' chuyển '+count+' quân từ '+mapData.territories[from].name+' sang '+mapData.territories[to].name+'.', pid);
      host.renderGame();
      return {ok:true, result:{from, to, count}};
    }
    case 'endTurn': {
      if(game.phase!=='fortify') return fail('wrong_phase');
      endTurn();
      return {ok:true, result:{}};
    }
  }
  return fail('bad_action');
}

/* ---- src/js/05-ai.js ---- */
/* =========================================================================
   AI LOGIC
   ---------------------------------------------------------------------
   No external file/spec — this comment block IS the AI's "design doc".
   Every decision is a simple weighted-scoring heuristic, not lookahead/
   minimax or ML. But the turn isn't just four independently-scored steps
   run back to back — it starts with ONE overall campaign decision that the
   rest of the turn serves:

   0. TURN INTENT (see pickAITurnIntent()): before touching any armies, the
      AI looks at the WHOLE board once and commits to a single campaign for
      the turn — finish a continent, kill off a crippled opponent, brace a
      threatened border, or just push at its weakest front. Reinforce,
      attack AND fortify then all read that same intent and bias their
      scoring toward it, instead of each step re-deciding "what matters"
      from scratch in isolation. This is the one part of the AI that
      resembles how a human actually plans a turn.

   Everything below is scoring detail for the four steps that CARRY OUT that
   intent, run in sequence (reinforce -> attack -> fortify -> end turn):

   1. RESERVE AWARENESS ("biết giữ quân"): before attacking FROM a territory,
      the AI first sets aside a defensive reserve sized to the strongest
      OTHER enemy neighbor that territory faces (see reserveFor()). Only the
      surplus above that reserve is considered "usable" for the attack-odds
      calculation, so a stack sitting next to a second, untouched threat
      won't get thrown entirely at the first juicy target. The reserve
      shrinks on Hard and grows on Easy (aggressiveThreshold in
      difficultyProfile()).
   2. CONTINENT AWARENESS ("giữ châu lục để ăn điểm"): capturing a territory
      that completes a continent gets a large score bonus (attackScore()),
      and reinforcement placement (pickAIReinforceTarget) favors defending
      the borders of continents the AI already fully owns, or pushing to
      finish one that's one territory away.
   3. KILL PRIORITY ("diệt hẳn player ngoắc ngoải"): an opponent reduced to
      very few territories is a soft target worth going a little out of your
      way for, because eliminating them transfers their whole card hand to
      the killer (see checkElimination) — the fewer territories/the more
      cards they're holding, the bigger the score bonus to finish them off.
      The AI is also more cautious about picking fights with whoever is
      currently the strongest player (evaluatePlayerPower), unless it's
      already comparably strong itself.
   4. PERSONALITY (per-AI flavor on top of difficulty): each AI player has a
      `personality` (see AI_PERSONALITIES) that nudges the same knobs — how
      big a reserve to keep, how eager to chase continents/kills — so AIs at
      the same difficulty still play distinctly from each other.
   5. ALLIANCE (optional, game.allianceEnabled): when on, and one player has
      pulled CLEARLY ahead of the field (findAllianceLeader() — margin-gated,
      not just "whoever's highest this turn"), every OTHER AI is reluctant to
      fight fellow non-leaders and instead prefers piling onto the leader — a
      loose "gang up on the leader" dynamic instead of every AI treating all
      rivals the same. The leader itself is exempt and just plays normally.
   ========================================================================= */

// Labels only — the numbers behind each personality (threshold shift, reserve multiplier, kill/
// continent bonus multipliers) live in the config (src/config.json, keys pers<Name>…, editable on
// the Cấu hình screen) and are read by personalityTraits() below. `cfgKey` is the <Name> part.
const AI_PERSONALITIES = {
  balanced:    { label:'Cân bằng',                cfgKey:'Balanced' },
  turtle:      { label:'Rùa (thủ chắc)',           cfgKey:'Turtle' },
  rusher:      { label:'Xông pha (háo chiến)',     cfgKey:'Rusher' },
  opportunist: { label:'Cơ hội (săn con mồi yếu)', cfgKey:'Opportunist' },
};
function personalityTraits(personality){
  const k = (AI_PERSONALITIES[personality] || AI_PERSONALITIES.balanced).cfgKey;
  return {
    thresholdAdj: RUNTIME_CONFIG['pers'+k+'ThresholdAdj'],
    reserveMult: RUNTIME_CONFIG['pers'+k+'ReserveMult'],
    killBonusMult: RUNTIME_CONFIG['pers'+k+'KillBonus'],
    continentBonusMult: RUNTIME_CONFIG['pers'+k+'ContinentBonus'],
  };
}

// Two gates the #1 player (by evaluatePlayerPower) must BOTH clear before the alliance
// mechanic (game.allianceEnabled) recognizes them as "the leader" worth ganging up on — see
// findAllianceLeader() below:
// (Both from the config — allianceLeaderVsField / allianceLeaderMargin.)
//  - allianceLeaderVsField: strong enough to threaten the WHOLE rest of the field,
//    not just edge out the closest rival — e.g. with 5 other players, being 1.2x the #2 player
//    means little if the #1 is still weaker than the other 4 combined, since they wouldn't
//    need to team up to handle him.
//  - allianceLeaderMargin: clearly ahead of the single closest rival specifically — without
//    this, a 1-army edge in an otherwise close 2-player-ish spread could still pass the field
//    check above.

// Alliance-specific "who's the leader" check — considers EVERY alive player (including
// whoever is currently acting), unlike the plain "wary of the strongest opponent" logic in
// attackScore() which only ever looks at OTHER players. That distinction matters here:
// without including self, the actual strongest player on the board could never recognize
// ITSELF as the leader, and would end up applying the "gang up"/reluctance bonuses to its own
// attacks instead of being exempt from them. Returns null when no one clears both gates above.
function findAllianceLeader(){
  const powers = game.players.filter(pl=>pl.alive)
    .map(pl=>({id:pl.id, power:evaluatePlayerPower(pl.id)}))
    .sort((a,b)=>b.power-a.power);
  if(powers.length<2) return null;
  const top = powers[0], rest = powers.slice(1);
  const restTotal = rest.reduce((s,x)=>s+x.power, 0);
  if(top.power < restTotal*RUNTIME_CONFIG.allianceLeaderVsField) return null;
  if(top.power < rest[0].power*RUNTIME_CONFIG.allianceLeaderMargin) return null;
  return top.id;
}

function difficultyProfile(diff, personality){
  // baseThreshold: minimum armies-vs-armies ratio required to attack at all.
  // reserveFactor: how much of a bordering third-party threat to keep in
  //   reserve rather than throw into an attack (higher = more cautious).
  // Both per difficulty, from the config (aiEasy…/aiNormal…/aiHard…).
  const d = diff==='easy' ? 'Easy' : diff==='hard' ? 'Hard' : 'Normal';
  const base = {baseThreshold: RUNTIME_CONFIG['ai'+d+'Threshold'], reserveFactor: RUNTIME_CONFIG['ai'+d+'Reserve']};
  const trait = personalityTraits(personality);
  return {
    baseThreshold: Math.max(1.05, base.baseThreshold + trait.thresholdAdj),
    reserveFactor: Math.max(0, base.reserveFactor * trait.reserveMult),
    killBonusMult: trait.killBonusMult,
    continentBonusMult: trait.continentBonusMult,
  };
}
function difficultyThreshold(diff){ return difficultyProfile(diff).baseThreshold; }

function evaluatePlayerPower(pid){
  const mine = ownedTerritories(pid);
  const armies = mine.reduce((s,id)=> s+(game.armies[id]||0), 0);
  // Reinforcement income (computeReinforcements(), 04-game-state.js: territory-count base +
  // any continent bonuses held) is a leading indicator of SNOWBALL potential, not just current
  // standing army — two players with identical armies/territories right now aren't equally
  // dangerous if one is pulling in twice the income every turn. Weighted up (×6) since its raw
  // range (roughly 3-20) would otherwise barely move a power score in the tens-to-hundreds range.
  // Armies weighted ×2 as the main immediate-threat signal; territory count only ×1 now — its
  // significance is already mostly captured via reinforcements (which derives from it directly),
  // so it's kept around just as a small tie-breaker rather than double-counted at full weight.
  // (Weights from the config — powerWeightArmies / …Territories / …Reinforcements.)
  const reinforcements = computeReinforcements(pid);
  const C = RUNTIME_CONFIG;
  return armies*C.powerWeightArmies + mine.length*C.powerWeightTerritories + reinforcements*C.powerWeightReinforcements;
}

// Would owning `terrId` complete every territory of its continent for `pid`?
function completesContinentFor(pid, terrId){
  const t = mapData.territories[terrId];
  if(!t || t.continentId==null) return false;
  const contTerrs = Object.values(mapData.territories).filter(x=>x.continentId===t.continentId);
  return contTerrs.every(x=> x.id===terrId || game.owner[x.id]===pid);
}

// ---------------------------------------------------------------------
// TURN INTENT ("chiến lược tổng thể của lượt"): computed ONCE at the start
// of the turn (aiRunFullTurn), before reinforce/attack/fortify run. Rather
// than each of those three steps scoring its own options in isolation, they
// all read the same `intent` and bias their scoring toward it — a turn spent
// "closing out a continent" reinforces, attacks AND fortifies toward that
// continent instead of three unrelated locally-greedy choices that just
// happen to run back to back. This mirrors how a human plans a turn: look at
// the whole board first, decide the ONE thing this turn is for, then spend
// every action in service of that — rather than re-deciding from scratch at
// every step.
//
// Picked in priority order, first match wins (a human commits to one
// campaign per turn, not several at once):
//   1. finish_continent — one territory away from completing a continent,
//      and that missing territory already borders one of mine (i.e. it's
//      actually reachable this turn, not just "close" on the map).
//   2. kill_weak        — a live opponent down to <=2 territories exists and
//      borders one of mine (finishing them off steals their whole hand).
//   3. defend           — my worst-outgunned border is badly threatened and
//      I'm not the strongest player on the board (can't afford to ignore it
//      to go adventuring elsewhere).
//   4. expand           — no urgent campaign: fall back to pushing at my
//      weakest local front (same territory `defend` would have picked, just
//      without the "danger" framing).
function pickAITurnIntent(pid){
  const mine = ownedTerritories(pid);
  const myPower = evaluatePlayerPower(pid);
  const opponents = game.players.filter(pl=>pl.alive && pl.id!==pid);
  let leaderPower = -1;
  opponents.forEach(pl=>{ leaderPower = Math.max(leaderPower, evaluatePlayerPower(pl.id)); });

  const continentIds = new Set(mine.map(id=>mapData.territories[id].continentId).filter(c=>c!=null));
  for(const contId of continentIds){
    const contTerrs = Object.values(mapData.territories).filter(t=>t.continentId===contId);
    const missing = contTerrs.filter(t=>game.owner[t.id]!==pid);
    if(missing.length===1 && [...missing[0].neighbors].some(n=>game.owner[n]===pid)){
      return {type:'finish_continent', continentId:contId, focusTerrId:missing[0].id};
    }
  }

  let weakTarget=null, weakCount=Infinity;
  opponents.forEach(pl=>{
    const terrs = ownedTerritories(pl.id);
    if(terrs.length===0 || terrs.length>2) return;
    const reachable = terrs.some(tid=>[...mapData.territories[tid].neighbors].some(n=>game.owner[n]===pid));
    if(reachable && terrs.length<weakCount){ weakCount=terrs.length; weakTarget=pl.id; }
  });
  if(weakTarget!=null) return {type:'kill_weak', targetPlayerId:weakTarget};

  let worstBorder=null, worstDeficit=-Infinity;
  mine.forEach(id=>{
    const t = mapData.territories[id];
    const enemyNb = [...t.neighbors].filter(n=>game.owner[n]!==pid);
    if(!enemyNb.length) return;
    const maxEnemy = Math.max(...enemyNb.map(n=>game.armies[n]));
    const deficit = maxEnemy - game.armies[id];
    if(deficit>worstDeficit){ worstDeficit=deficit; worstBorder=id; }
  });
  if(worstBorder!=null && worstDeficit>=2 && myPower<leaderPower){
    return {type:'defend', focusTerrId:worstBorder};
  }

  return {type:'expand', focusTerrId:worstBorder};
}

function pickAIReinforceTarget(pid, mine, intent){
  // Same gang-up logic as aiAttackStep's reserveFor(): once a runaway leader has locked every
  // other AI into "attack only the leader" this turn, a border facing a fellow non-leader isn't
  // a real threat (they won't attack it either) — so new reinforcements shouldn't be pulled
  // toward defending it. Only borders facing the leader still count as under threat.
  const allianceLeaderId = game.allianceEnabled ? findAllianceLeader() : null;
  const mustOnlyDefendAgainstLeader = allianceLeaderId!=null && pid!==allianceLeaderId;
  // This turn's single-minded focus, if it has one: the gang-up leader (forced on every other
  // AI), or — for the leader itself, or anyone else not under that lock — a kill_weak intent's
  // chosen victim. Below, a border facing this focus wins outright over every other border,
  // regardless of score, so reinforcement actually piles into one decisive spearhead instead of
  // the base score's tendency to spread just-enough parity across every front at once (the base
  // "maxEnemyArmy - myArmy" term only ever tries to level the score, never to overwhelm it).
  const focusPlayerId = mustOnlyDefendAgainstLeader ? allianceLeaderId
    : (intent && intent.type==='kill_weak' ? intent.targetPlayerId : null);
  let best=null, bestScore=-Infinity;
  let bestFocus=null, bestFocusScore=-Infinity;
  mine.forEach(id=>{
    const t = mapData.territories[id];
    const enemyNb = [...t.neighbors].filter(n=>game.owner[n]!==pid);
    if(enemyNb.length===0) return; // only border territories are worth reinforcing
    const threatNb = mustOnlyDefendAgainstLeader ? enemyNb.filter(n=>game.owner[n]===allianceLeaderId) : enemyNb;
    const maxEnemyArmy = threatNb.length ? Math.max(...threatNb.map(n=>game.armies[n])) : 0;
    let score = maxEnemyArmy - game.armies[id];
    if(t.continentId!=null){
      const contTerrs = Object.values(mapData.territories).filter(x=>x.continentId===t.continentId);
      const ownedCount = contTerrs.filter(x=>game.owner[x.id]===pid).length;
      if(ownedCount===contTerrs.length) score += 1.5;       // defend a continent I already hold
      else if(ownedCount>=contTerrs.length-1) score += 0.8; // one territory away from completing it
    }
    // Nudge reinforcement toward wherever this turn's chosen campaign (see
    // pickAITurnIntent) is actually happening, so troops don't land on some
    // unrelated border just because it scored marginally higher locally.
    if(intent){
      if(intent.type==='finish_continent' && t.continentId===intent.continentId) score += 1.2;
      else if(intent.type==='kill_weak' && enemyNb.some(n=>game.owner[n]===intent.targetPlayerId)) score += 1.2;
      else if((intent.type==='defend'||intent.type==='expand') && id===intent.focusTerrId) score += 1.0;
    }
    if(focusPlayerId!=null && enemyNb.some(n=>game.owner[n]===focusPlayerId)){
      if(score>bestFocusScore){ bestFocusScore=score; bestFocus=id; }
    }
    if(score>bestScore){ bestScore=score; best=id; }
  });
  if(focusPlayerId!=null && bestFocus!=null) return bestFocus;
  if(best===null) best = randChoice(mine);
  return best;
}

function aiRunFullTurn(pid){
  host.setActionHint(game.players[pid].name+' đang suy nghĩ...');
  const intent = pickAITurnIntent(pid);
  aiSchedule(()=>{ aiReinforceStep(pid, intent); }, aiDelay(300));
}

function aiReinforceStep(pid, intent){
  intent = intent || pickAITurnIntent(pid); // e.g. resuming a save mid-phase, see importGameJSON
  const p = game.players[pid];
  aiTryTradeCards(p);
  let guard=0;
  while(game.reinforceRemaining>0 && guard++<200){
    const mine = ownedTerritories(pid);
    const target = pickAIReinforceTarget(pid, mine, intent);
    game.armies[target]++;
    game.reinforceRemaining--;
  }
  host.renderGame();
  aiSchedule(()=> aiAttackStep(pid, intent), aiDelay(350));
}

function aiTryTradeCards(p){
  let guard=0;
  // How willing the AI is to hold a valid combo instead of cashing it in immediately depends
  // on which trade rule is active (see tradeInValue() for what each rule means):
  //  - progressive: the shared global count only goes up, so a LATER trade always pays MORE —
  //    holding is a real (if risky, since forced at 5 cards) strategy, so hold fairly often.
  //  - fixed: value plateaus at a fixed cap, so once there, waiting gains nothing — trade ASAP.
  //  - exponential: only the player's OWN trade count matters, and it compounds — the sooner
  //    (and more often) this AI personally trades, the faster ITS OWN future trades ramp up, so
  //    trade ASAP rather than sitting on cards that aren't growing in value by waiting.
  const holdChance = game.tradeRule==='progressive' ? 0.7 : 0.1;
  while(guard++<10){
    const combo = findTradeCombo(p.cards);
    const forced = p.cards.length>=5;
    if(!combo) break;
    if(!forced && random()<holdChance && p.cards.length<5) break; // sometimes hold cards
    tradeCards(p, combo);
  }
}

function findTradeCombo(cards){
  if(cards.length<3) return null;
  for(let i=0;i<cards.length;i++) for(let j=i+1;j<cards.length;j++) for(let k=j+1;k<cards.length;k++){
    const set=[cards[i],cards[j],cards[k]];
    const uniq = new Set(set);
    if(uniq.size===1 || uniq.size===3) return [i,j,k];
  }
  return null;
}

function tradeCards(p, indices){
  const idxSorted = indices.slice().sort((a,b)=>b-a);
  const removed = idxSorted.map(i=>p.cards[i]);
  idxSorted.forEach(i=> p.cards.splice(i,1));
  game.tradeCount++;
  p.personalTradeCount = (p.personalTradeCount||0)+1;
  const value = tradeInValue(game.tradeRule, game.tradeCount, p.personalTradeCount);
  p.totalReinforced += value;
  if(game.phase==='reinforce' && currentPlayerId()===p.id){
    game.reinforceRemaining += value;
  } else {
    game.pool[p.id] = (game.pool[p.id]||0) + value;
  }
  logMsg('info', p.name+' đổi thẻ bài lấy '+value+' quân.', p.id);
  host.renderGame();
}

function aiAttackStep(pid, intent){
  intent = intent || pickAITurnIntent(pid); // e.g. resuming a save mid-phase, see importGameJSON
  game.phase='attack';
  const p = game.players[pid];
  const profile = difficultyProfile(game.difficulty, p.personality);
  const opponents = game.players.filter(pl=>pl.alive && pl.id!==pid);
  const myPower = evaluatePlayerPower(pid);
  let leaderId = null, leaderPower = -1;
  opponents.forEach(pl=>{ const pw = evaluatePlayerPower(pl.id); if(pw>leaderPower){ leaderPower=pw; leaderId=pl.id; } });
  // Only computed when the setting is on — findAllianceLeader() scans every alive player
  // (self included) and requires a real margin over the runner-up (see its own comment).
  const allianceLeaderId = game.allianceEnabled ? findAllianceLeader() : null;
  const iAmAllianceLeader = pid!=null && pid===allianceLeaderId;
  // Hard gang-up: once there's a runaway leader, every other AI attacks ONLY the leader's
  // territories this turn — no picking on a fellow underdog instead, no falling back to
  // opportunistic expansion elsewhere. If nothing of theirs borders the leader, they simply
  // don't attack at all this turn (see the candidate-loop filter in step() below, and the
  // "no legal attack" path at bestOpt===null, which already skips straight to fortify).
  const mustOnlyAttackLeader = allianceLeaderId!=null && !iAmAllianceLeader;

  // How many armies a territory should keep in reserve, sized to the strongest
  // enemy neighbor it borders OTHER than the one currently being considered.
  // Once gang-up mode is active (mustOnlyAttackLeader), every other non-leader AI is under the
  // same rule — none of them will attack anywhere but the leader this turn either — so a fellow
  // non-leader neighbor isn't a real threat right now. Only the leader's own bordering
  // territories still justify holding troops back; everything else is freed up to go into the
  // leader front instead of sitting idle "just in case" against an ally.
  function reserveFor(fromId, excludeTo){
    const t = mapData.territories[fromId];
    let maxOther = 0;
    t.neighbors.forEach(n=>{
      if(n===excludeTo) return;
      if(game.owner[n]===pid) return;
      if(mustOnlyAttackLeader && game.owner[n]!==allianceLeaderId) return;
      maxOther = Math.max(maxOther, game.armies[n]);
    });
    return Math.ceil(maxOther*profile.reserveFactor);
  }

  function attackScore(fromId, toId){
    const usable = Math.max(0, game.armies[fromId]-1-reserveFor(fromId,toId));
    if(usable<1) return null; // nothing safe to attack with once the reserve is set aside
    const singleRatio = (usable+1)/Math.max(1,game.armies[toId]);
    // Area-level superiority: every OTHER territory of mine that also borders `toId` counts as
    // backup for a coordinated campaign, not just `fromId` in isolation — a target flanked by two
    // of my stacks is winnable in a 2-move campaign even if neither stack alone clears the odds
    // bar on its own, the same way a human wouldn't size up a contested border by just one
    // province. step() re-evaluates after every attack, so a weaker opening strike here naturally
    // sets up whichever territory follows to finish off whatever's left standing.
    // Blended with (not replacing) the single-territory ratio rather than used outright: this
    // particular attack only actually commits `fromId`'s own army, so full credit for strength
    // that hasn't swung yet — and might get spent elsewhere, or lost first — would be overconfident.
    let areaUsable = usable;
    mapData.territories[toId].neighbors.forEach(nb=>{
      if(nb!==fromId && game.owner[nb]===pid) areaUsable += Math.max(0, game.armies[nb]-1-reserveFor(nb,toId));
    });
    const ratio = areaUsable>usable ?
      (singleRatio + (areaUsable+1)/Math.max(1,game.armies[toId]))/2 : singleRatio;
    let bonus = 0;
    if(completesContinentFor(pid, toId)) bonus += 2.5*profile.continentBonusMult;
    const defenderId = game.owner[toId];
    const defP = defenderId!=null ? game.players[defenderId] : null;
    if(defP){
      const defTerrCount = ownedTerritories(defenderId).length;
      if(defTerrCount<=2) bonus += (1.5 + defP.cards.length*0.4)*profile.killBonusMult; // finish them off for the cards
      if(defenderId===leaderId && myPower<leaderPower*1.1) bonus -= 0.6; // wary of picking a fight I can't afford
      // mustOnlyAttackLeader's candidate-loop filter (see step()) already guarantees
      // defenderId===allianceLeaderId here whenever that's active — this just makes the AI
      // more willing to accept worse odds against the leader specifically (lowers
      // effectiveThreshold via bestEval.bonus) rather than walking away from a marginal fight.
      if(mustOnlyAttackLeader && defenderId===allianceLeaderId) bonus += 1.2;
    }
    // Keep this attack aligned with this turn's chosen campaign (see
    // pickAITurnIntent) instead of chasing whatever pair scores highest in
    // isolation this round.
    if(intent.type==='finish_continent' && mapData.territories[toId].continentId===intent.continentId) bonus += 0.8;
    else if(intent.type==='kill_weak' && defenderId===intent.targetPlayerId) bonus += 1.0;
    else if(intent.type==='defend') bonus -= 0.3; // hold back this turn rather than adventure elsewhere
    return {ratio, score:ratio+bonus, bonus};
  }

  // Fights repeated silent rounds against the same target while the attack is still
  // profitable (reserve/threshold re-checked every round, since armies shrink round by
  // round), so a huge army-count mismatch resolves in one go instead of needing hundreds
  // of individually-delayed AI turns. Only the final round's dice are shown, and all the
  // rounds get folded into one combat-log line, since the in-between rounds have no delay
  // to actually be seen anyway.
  const BATCH_GUARD = 5000;
  // force: skip the normal odds threshold (still bound by attackScore's reserve/usable
  // safety floor, just not "is this a good idea") — used by the "guarantee a card every
  // turn" rule below to push through a marginal fight it would otherwise walk away from.
  function battleBatch(fromId, toId, fromName, toName, defenderName, force){
    let rounds=0, attLossTotal=0, defLossTotal=0, captured=false, lastRes=null;
    while(rounds<BATCH_GUARD){
      if(game.armies[fromId]<2) break;
      const ev = attackScore(fromId, toId);
      if(!ev) break;
      if(!force){
        const threshold = Math.max(1.05, profile.baseThreshold - ev.bonus*0.3);
        if(ev.ratio<threshold) break;
      }
      lastRes = doBattle(fromId, toId, {silent:true});
      rounds++;
      attLossTotal += lastRes.attLoss;
      defLossTotal += lastRes.defLoss;
      // Recorded every round (not just once after the loop) so that if THIS round's capture
      // ends the game (checkElimination -> checkWinCondition -> showGameOver runs synchronously
      // inside doBattle, before control even returns here), the summary screen already reflects
      // this battle's running total instead of a stale earlier record.
      recordBattleStat(p.name, defenderName, fromName, toName, attLossTotal+defLossTotal);
      if(lastRes.captured){ captured=true; break; }
    }
    return {rounds, attLossTotal, defLossTotal, captured, lastRes};
  }

  // Disabled: this used to force a below-threshold attack once per turn so every AI was
  // guaranteed at least 1 card-earning action (a capture under 'on_capture'/default, a kill under
  // 'on_kill'). Turned off per request — now AI purely attacks on odds (plus the area-superiority
  // bonus in attackScore() above), never gambles into a bad fight just to chase a card. A
  // genuinely gridlocked board (no attacker anywhere clears the odds bar) can now go whole turns,
  // or in the extreme a whole game, without anyone drawing a card.
  function stillNeedsCardThisTurn(){
    return false;
  }

  let guard=0;
  function step(){
    if(game.over) return;
    guard++;
    if(guard>60){ game.selectedFrom=null; game.selectedTo=null; aiFortifyStep(pid, intent); return; }
    const mine = ownedTerritories(pid);
    let bestOpt=null, bestEval=null;
    for(const from of mine){
      if(game.armies[from]<2) continue;
      const t = mapData.territories[from];
      for(const to of t.neighbors){
        if(game.owner[to]===pid) continue;
        if(mustOnlyAttackLeader && game.owner[to]!==allianceLeaderId) continue;
        const ev = attackScore(from, to);
        if(!ev) continue;
        if(!bestEval || ev.score>bestEval.score){ bestEval=ev; bestOpt={from,to}; }
      }
    }
    // bonuses (continent completion / finishing off a weak player) justify taking slightly
    // worse pure odds than the difficulty's base threshold would normally allow.
    const effectiveThreshold = bestEval ? Math.max(1.05, profile.baseThreshold - bestEval.bonus*0.3) : Infinity;
    const meetsThreshold = !!bestOpt && bestEval.ratio>=effectiveThreshold;
    const forcedForCard = !meetsThreshold && !!bestOpt && stillNeedsCardThisTurn();
    if(!bestOpt || (!meetsThreshold && !forcedForCard)){
      game.selectedFrom=null; game.selectedTo=null;
      aiFortifyStep(pid, intent); return;
    }

    const { from, to } = bestOpt;
    // Same selectedFrom/selectedTo the human attack UI uses — this is what makes the pulsing
    // badges and the animated arrow (drawGameCanvas, see attackAnim in 06-render-game.js) show
    // up for an AI's move too, not just a human's. Shown for one aiDelay() beat (the AI's
    // existing "thinking" pause, previously just empty wait time) before actually fighting.
    game.selectedFrom = from; game.selectedTo = to;
    host.renderGame();
    if(game.over) return;
    aiSchedule(()=> executeAttack(from, to, forcedForCard), aiDelay(260));
  }
  function executeAttack(from, to, forcedForCard){
    if(game.over) return;
    const fromName = mapData.territories[from].name, toName = mapData.territories[to].name;
    const defenderId = game.owner[to];
    const defenderName = game.players[defenderId].name;
    const attackerColor = p.color, defenderColor = game.players[defenderId].color;
    if(forcedForCard) logMsg('info', p.name+' liều đánh '+toName+' để kiếm bài.', [pid, defenderId]);
    const fromCountBefore = game.armies[from], toCountBefore = game.armies[to];
    const result = battleBatch(from, to, fromName, toName, defenderName, forcedForCard);
    const fromCountAfter = game.armies[from], toCountAfter = game.armies[to];
    function nextDecision(){
      game.selectedFrom=null; game.selectedTo=null;
      if(game.over) return;
      // Deliberately NOT aiDelay() here: in spectator mode that ignores its argument and always
      // waits the full configured spectator delay — stacking a second one of those on top of the
      // one already spent before the strike (see step()) plus the ~1.1s attackAnim itself would
      // make every attack take several seconds. The animation just played already gave viewers
      // something to watch; this is just a small breather before the next decision, not a second
      // full "thinking pause".
      aiSchedule(step, 80);
    }
    if(result.rounds<=0){ host.renderGame(); nextDecision(); return; }
    const roundsLabel = result.rounds>1 ? ` (${result.rounds} hiệp)` : '';
    logMsg('attack', `${p.name} tấn công ${toName} từ ${fromName}${roundsLabel}: mất ${result.attLossTotal}, đối phương mất ${result.defLossTotal}.`, [pid, defenderId]);
    if(result.lastRes) host.showDice(result.lastRes.ad, result.lastRes.dd, result.lastRes.results);
    if(result.captured) logMsg('capture', `${p.name} chiếm được ${toName}!`, [pid, defenderId]);
    // startAttackAnim's onDone fires once the fly/impact/return sequence finishes (see
    // 06-render-game.js) — the next attack decision waits for that instead of firing right
    // after the battle resolves, same as the human attack flow.
    host.startAttackAnim({
      fromId:from, toId:to, attLoss:result.attLossTotal, defLoss:result.defLossTotal, captured:result.captured,
      fromCountBefore, toCountBefore, fromCountAfter, toCountAfter, attackerColor, defenderColor,
    }, nextDecision);
    host.renderGame();
  }
  step();
}

function aiFortifyStep(pid, intent){
  intent = intent || pickAITurnIntent(pid); // e.g. resuming a save mid-phase, see importGameJSON
  game.phase='fortify';
  host.renderGame();
  const p = game.players[pid];
  // Same gang-up detection as aiAttackStep/pickAIReinforceTarget — a forced leader-only turn is
  // also this turn's fortify front, not just this turn's attack target, so troops actually pile
  // up where the AI is allowed to strike instead of wherever pickAITurnIntent's unrelated
  // continent/kill_weak/defend logic happened to land independently of the alliance rule.
  const allianceLeaderId = game.allianceEnabled ? findAllianceLeader() : null;
  const mustOnlyAttackLeader = allianceLeaderId!=null && pid!==allianceLeaderId;
  // move armies from every safe interior territory to the front
  const mine = ownedTerritories(pid);
  const interior = mine.filter(id=>{
    const t = mapData.territories[id];
    return [...t.neighbors].every(n=>game.owner[n]===pid) && game.armies[id]>1;
  });
  const borders = mine.filter(id=>{
    const t = mapData.territories[id];
    return [...t.neighbors].some(n=>game.owner[n]!==pid);
  });
  // A border isn't just "a border" — prefer whichever one IS this turn's
  // chosen campaign (see pickAITurnIntent) before falling back to whichever
  // border a path happens to reach first, so the army sent forward actually
  // lands on next turn's front instead of a border unrelated to the plan.
  function isIntentFront(id){
    const t = mapData.territories[id];
    if(mustOnlyAttackLeader) return [...t.neighbors].some(n=>game.owner[n]===allianceLeaderId);
    if(intent.type==='finish_continent') return t.continentId===intent.continentId;
    if(intent.type==='kill_weak') return [...t.neighbors].some(n=>game.owner[n]===intent.targetPlayerId);
    return id===intent.focusTerrId; // defend / expand
  }
  const orderedBorders = [...borders].sort((a,b)=> (isIntentFront(b)?1:0) - (isIntentFront(a)?1:0));
  // A human player can make as many fortify moves as they like before ending their turn, so drain
  // EVERY interior territory with spare troops in this one pass instead of just the single
  // largest one — otherwise every other interior garrison stays stranded forever wherever it
  // happened to end up (typically the bare-minimum 1 army left right after a capture), since
  // nothing else in the game ever revisits it. Moves are tallied per destination so multiple
  // interior sources funneling into the same front log as one summary line each, not a spammy
  // line per source.
  const movedTo = {};
  if(orderedBorders.length){
    interior.forEach(src=>{
      let bestDst=null;
      for(const dst of orderedBorders){
        if(pathExistsOwned(src,dst,pid)){ bestDst=dst; break; }
      }
      if(bestDst){
        const moving = game.armies[src]-1;
        if(moving>0){
          game.armies[src]-=moving; game.armies[bestDst]+=moving;
          movedTo[bestDst] = (movedTo[bestDst]||0)+moving;
        }
      }
    });
  }
  Object.keys(movedTo).forEach(dstId=>{
    logMsg('info', p.name+' tăng cường '+movedTo[dstId]+' quân đến '+mapData.territories[dstId].name+'.', pid);
  });
  host.renderGame();
  aiSchedule(()=> endTurn(), aiDelay(400));
}

